window.__YB_RAW__ = [{"id":"black_myth_wukong","name":"黑神话：悟空","titleMain":"黑神话：悟空","titleSub":"Black Myth: Wukong","short":"黑神话","genre":"动作角色扮演","currentPct":61,"nameEn":"Black Myth: Wukong","developer":"Game Science","year":2024,"steamAppId":2358720,"totalHoursMain":25,"totalHoursComplete":55,"bannerUrl":"assets/covers/black_myth_wukong-banner.jpg","posterUrl":"assets/covers/black_myth_wukong-poster.jpg","overview":{"tagline":"天命人，踏上取经路","description":"黑神话：悟空是一款以《西游记》为底本的动作角色扮演游戏，由国产工作室 Game Science 历时六年打造。你扮演\"天命人\"——一只被命运选中的猴子，踏上追寻孙悟空遗留神通与真相的旅程。这不是重讲西游取经，而是一个关于\"那个故事之后\"的反思：自由被驯服，传奇被遗忘，被压抑的本性如何在轮回中寻求解脱。游戏以魂系战斗为骨架，以东方神话美学为皮，Boss战难度极高但叙事厚度罕见——每一场战斗背后都藏着一段被正史忽略的命运。","highlights":[{"icon":"⚔️","text":"满屏幕的视觉奇观：每一个Boss都是一件艺术品"},{"icon":"📖","text":"西游之外的西游：原著熟悉者会发现惊人的隐线"},{"icon":"🔥","text":"牛魔王决战是近年最史诗的Boss战体验之一"},{"icon":"🎭","text":"结局双分叉：你的选择决定了这个故事的意义"}]},"entryPoints":[{"progressPct":0,"label":"推荐起点：完整体验","reason":"从头开始，感受天命人从觉醒到成长的完整弧线。黑风山是绝佳的新手引导，世界观铺垫扎实。"},{"progressPct":43,"label":"战斗体验最佳入口","reason":"第三回开始时你已掌握变化术和多套棍势，战斗系统完全展开。从这里开始故事密度也大幅提升。"},{"progressPct":63,"label":"剧情高潮直接入场","reason":"第四回流沙河是剧情反转密集段，天命人身份之谜、悟空记忆碎片开始拼合，适合想快速体验核心叙事的玩家。"}],"protagonistJourney":[{"progressPct":0,"event":"觉醒·踏入黑风山","description":"天命人从沉眠中醒来，什么都不知道，只有本能。他的战斗语言从这里开始建立。","unlocks":["基础棍法","轻棍·重棍连招","法力初解锁"]},{"progressPct":16,"event":"毗蓝婆赐法·变化术初得","description":"击败黑熊精后，毗蓝婆出现，揭示袈裟背后的因果，天命人得到第一个变化（化身）。","unlocks":["变化术（化身）","黑熊精精魄","第一件装备套件"]},{"progressPct":28,"event":"黄风散——感知突破","description":"黄风大圣的三昧神风迫使天命人学会在视野受损时凭感觉战斗，完美闪避的肌肉记忆真正形成。","unlocks":["定身法术强化","风系抗性","第二变化解锁"]},{"progressPct":47,"event":"小雷音·见识虚伪","description":"击败黄眉后，天命人第一次理解：权力和信仰都可以是谎言，他的旅途不是朝圣，而是解构。","unlocks":["金箍棒第二形态","佛系法术","蓄力棍势解锁"]},{"progressPct":63,"event":"流沙河·碎片拼合","description":"悟空的记忆碎片开始真正涌入，天命人意识到自己与悟空之间的联系远不止\"使者\"那么简单。","unlocks":["沙僧神通","水系护符","棍势第三套"]},{"progressPct":77,"event":"牛魔王决战·力量巅峰","description":"这是天命人战斗能力的顶点时刻——以全套神通独自对抗全游戏最强的Boss，也是精神上的一次顿悟。","unlocks":["牛魔神通","最强变化形态","第五法术槽位"]},{"progressPct":88,"event":"真假之战·明白自己是谁","description":"六耳猕猴之战后，天命人终于明白：他不是在追寻悟空，他就是悟空的一部分。选择在这里分叉。","unlocks":["六耳神通","双结局解锁","真结局前置条件"]}],"gameTheme":{"bg":"#0c0a06","bgCard":"#161008","accent":"#d4a017","accent2":"#c0392b","text":"#f0e6d0"},"chapters":[{"id":0,"name":"第一回：黑风山","planet":"黑风山·黑风洞","progressStart":0,"progressEnd":16,"hypeScore":7,"keyEvent":"天命人初醒，破入黑风山，斩黑熊精，寻觅毗蓝婆","plotDetail":"黑风山是天命人踏入世界的第一片土地——阴暗、潮湿、古寺与熊洞交错。这里曾是悟空取经路上遭遇麻烦的地方，而今妖王横行，袈裟下落不明。天命人从混沌中醒来，只凭本能前行，对自己的使命一无所知，只知道：要往前走。","playerGoals":"找到袈裟的下落 → 击败广智与黑熊精 → 获得毗蓝婆的认可，开启旅途","newCharacters":"广智（执念老僧）、黑熊精（山中妖王）、毗蓝婆（神秘菩萨，战后登场）"},{"id":1,"name":"第二回：黄风岭","planet":"黄风岭·风沙之境","progressStart":16,"progressEnd":32,"hypeScore":7,"keyEvent":"穿越黄沙，败虎先锋，斩黄风大圣，得灵根线索","plotDetail":"黄风岭是一片被永久黄沙笼罩的荒地，飞沙走石，能见度极低。黄风大圣用三昧神风统治这片土地，但沙的背后藏着一个更古老的秘密——这场沙暴不是天灾，是一种牺牲。天命人在能见度极差的环境中以感觉代替视觉，战斗本能进一步觉醒。","playerGoals":"穿越沙暴到达黄风大圣的巢穴 → 击败虎先锋（前置关卡）→ 斩黄风大圣，揭开黄沙的真正来源","newCharacters":"虎先锋（忠勇大将）、黄风大圣（飞鼠妖王，守护者与暴君的两面）、鼠将（隐线角色）"},{"id":2,"name":"第三回：小雷音寺","planet":"盘丝岭·小雷音寺","progressStart":32,"progressEnd":49,"hypeScore":8,"keyEvent":"蜘蛛精迷局，金池长老之秘，斩黄眉，见菩提真身","plotDetail":"第三回分为两段：盘丝岭的蜘蛛幻境，和小雷音寺的虚假佛堂。前者以迷幻和感知考验为主，后者以讽刺和欺骗为核心——黄眉大王打造了一个以谎言维系的\"极乐世界\"。本回还隐藏着菩提老祖的痕迹，是全游戏叙事层次最丰富的一回。","playerGoals":"在盘丝洞中识破蜘蛛精的幻阵 → 探寻金池长老的过去 → 进入小雷音寺，击破黄眉大王的自欺欺人","newCharacters":"蜘蛛精姐妹（幻术猎手）、黄眉大王（弥勒的扫塔力士，自封如来）、菩提老祖（隐线，悟空的老师）"},{"id":3,"name":"第四回：流沙河","planet":"流沙河·沙漠腹地","progressStart":49,"progressEnd":63,"hypeScore":8,"keyEvent":"天命人真相初现，沙僧本质揭露，悟空记忆碎片浮现","plotDetail":"流沙河是干涸的荒漠，但水下埋着更深的秘密。沙僧的真实面目在这一回逐渐浮现，而更重要的是天命人开始以碎片化的方式\"记起\"一些不属于自己的记忆——悟空经历过的战斗、情感和抉择。这是玩家第一次真正意识到：天命人追寻的，不只是一段历史。","playerGoals":"渡过流沙河，揭开沙僧真相 → 收集悟空记忆碎片 → 理解天命人与悟空之间更深的联系","newCharacters":"沙僧（流沙河的守望者，隐藏着复杂的过去）、流沙河中的隐线精怪"},{"id":4,"name":"第五回：火焰山","planet":"火焰山·芭蕉洞","progressStart":63,"progressEnd":80,"hypeScore":9,"keyEvent":"红孩儿再战，铁扇公主的抉择，牛魔王终极决战","plotDetail":"火焰山是全游戏情感浓度最高的一回。这里有一个破碎的家庭：牛魔王迷失于名利，铁扇公主独守芭蕉洞，红孩儿用愤怒掩盖孤独。三昧真火燃烧的不只是山头，也是一段再也回不去的往昔。牛魔王决战是全游戏最史诗的Battle，也是最让人心碎的结局。","playerGoals":"穿越火焰山的三昧真火 → 击败红孩儿（牛魔王决战前置）→ 史诗四阶段决战击败牛魔王","newCharacters":"红孩儿（牛魔王之子，三昧真火）、铁扇公主（芭蕉扇主人，悲情守护者）、牛魔王（最悲剧的Boss）"},{"id":5,"name":"第六回：灵山","planet":"灵山·天庭","progressStart":80,"progressEnd":100,"hypeScore":10,"keyEvent":"六耳猕猴真相，天命人的宿命，悟空的轮回与解脱","plotDetail":"一切谜底在灵山揭晓。天命人站在灵山门前，终于明白了自己是谁、这段旅程意味着什么。六耳猕猴的出现是最终也是最深刻的镜像：那个被压抑的自由本性，正在等待与自己决战。普通结局顺应轮回，真结局打破枷锁——你选择哪种答案？","playerGoals":"登上灵山，面对终极真相 → 与六耳猕猴决战（自我对决）→ 做出最终选择：顺应轮回或打破宿命","newCharacters":"六耳猕猴（悟空的镜像，自由本性的化身）、天庭诸神（背景势力完整登场）"}],"hypePeaks":[{"progressPct":7,"label":"广智之死","score":6,"color":"#d4a017"},{"progressPct":14,"label":"黑熊精","score":8,"color":"#f97316"},{"progressPct":28,"label":"黄风大圣","score":8,"color":"#eab308"},{"progressPct":40,"label":"蜘蛛精","score":7,"color":"#a855f7"},{"progressPct":47,"label":"黄眉大王","score":9,"color":"#f97316"},{"progressPct":57,"label":"天命真相","score":8,"color":"#a855f7"},{"progressPct":70,"label":"红孩儿","score":8,"color":"#ef4444"},{"progressPct":77,"label":"牛魔王","score":10,"color":"#ef4444"},{"progressPct":88,"label":"六耳猕猴","score":10,"color":"#ef4444"},{"progressPct":96,"label":"真结局","score":9,"color":"#a855f7"}],"achievements":[{"steamId":"ACH_CH1_ENTER","name":"踏上征途","progressPct":3},{"steamId":"ACH_BLACK_BEAR","name":"黑风山已无妖风","progressPct":14},{"steamId":"ACH_YELLOW_WIND","name":"黄沙散尽","progressPct":28},{"steamId":"ACH_SPIDER","name":"蛛丝断","progressPct":40},{"steamId":"ACH_HUANGMEI","name":"小雷音已空","progressPct":47},{"steamId":"ACH_CH4_CLEAR","name":"流沙已平","progressPct":63},{"steamId":"ACH_BULL_KING","name":"火焰山熄","progressPct":77},{"steamId":"ACH_MACAQUE","name":"真假已辨","progressPct":88},{"steamId":"ACH_END_NORMAL","name":"踏破灵山","progressPct":92},{"steamId":"ACH_END_TRUE","name":"天命所归","progressPct":100}],"bossSaves":[{"id":"guangzhi","name":"广智 — 执念的开端","nameEn":"Guangzhi – The Abbot","folder":null,"progressPct":7,"storyGap":1,"planet":"黑风山·古寺","highlight":false,"context":{"plot":"广智是黑风山古寺的老方丈，本是一心向佛的僧人，却因迷恋那件袈裟而堕落。袈裟是悟空与唐僧过往因缘的遗物，广智守着它数百年，执念越深便越扭曲，最终以\"保护圣物\"为名成为了魔障。他是天命人踏入黑风山第一道真正的考验，也是游戏借佛法执念说的第一个故事：越是想抓住的东西，越会将人带入深渊。","characters":"广智：迷恋袈裟的老方丈，因\"执\"而堕，因\"执\"而亡。他的死不是坏人被惩罚，而是一个可悲的人终于解脱。\n\n天命人：第一次在这片土地上遭遇有名有姓的对手，战斗开始建立起自己的战斗语言。","gameplay":"广智是黑风山的引导级Boss，难度适中。他攻击节奏较慢，以横扫和顿击为主，适合练习闪避时机。进入第二阶段后会召唤火焰护体，增加伤害后摇。推荐：优先掌握完美闪避（白光一闪时闪）的手感，这个技巧之后全程都用得上。"}},{"id":"black_bear","name":"黑熊精 — 第一回终Boss","nameEn":"Black Bear Guai","folder":null,"progressPct":14,"storyGap":1,"planet":"黑风山·熊洞","highlight":true,"context":{"plot":"天命人是一只被命运选中的猴子，踏入黑风山寻找一件与悟空过去有关的袈裟。黑熊精（黑熊妖王）是山中真正的霸主，他偷走袈裟后觉得自己有了佛法庇佑。在《西游记》原著中悟空请来毗蓝婆才降服他，而本作中天命人需要独自面对。战斗结束后，毗蓝婆的出现揭示了袈裟背后一段被时间尘封的因果——这是悟空故事真正开始的第一块拼图。","characters":"天命人：主角，觉醒的猴子，命中注定追寻悟空踪迹。全程无台词，情感通过战斗和环境叙事表达。\n\n黑熊精：威猛的黑熊妖王，外表凶残，内心有自己的骄傲与执念。战斗结束后他的命运充满深意。\n\n广智（前置Boss）：迷恋袈裟的老和尚，因执念堕落，是黑风山第一道关卡。","gameplay":"三阶段Boss战。阶段一常规黑熊近战；阶段二黑焰覆体，攻击带燃烧DOT；阶段三愤怒形态，体型变大、速度加快、AOE扩大。推荐棍势劈棍+变化术（化身）应对第三阶段。携带定身法术可打断他的大招读条。"}},{"id":"tiger_vanguard","name":"虎先锋 — 黄风岭守将","nameEn":"Tiger Vanguard","folder":null,"progressPct":22,"storyGap":2,"planet":"黄风岭·虎穴","highlight":false,"context":{"plot":"踏入黄风岭后，天命人首先要面对的是黄风大圣麾下的首席大将——虎先锋。他是一只修炼成精的老虎，忠勇彪悍，为了守护主公的领地而战。但在他身上，你能感受到一丝与外表不符的沉重：他知道黄风大圣封印着什么，也知道这片黄沙笼罩的代价。虎先锋的失败，让黄风大圣意识到来者不善，开始亲自出手应对天命人。","characters":"虎先锋：黄风大圣的先锋大将，虎族出身，以忠义和战力著称。他的故事侧面反映了黄风岭妖族内部那种压抑已久的悲壮。\n\n黄风大圣（幕后）：虎先锋失败后才真正登场，虎先锋的存在是他性格与处境的第一层铺垫。","gameplay":"虎先锋攻击凶猛，以爪击和扑击为主，出招速度快于广智。核心技巧：他的扑击有明显的预备动作（蹲身），看到蹲身立刻侧闪，而非向后跳。第二阶段召唤风刃附体，攻击附加风系范围伤害。推荐棍势：劈棍破盾效果好，可中断他的部分蓄力。"}},{"id":"yellow_wind","name":"黄风大圣 — 第二回终Boss","nameEn":"Yellow Wind Sage","folder":null,"progressPct":28,"storyGap":2,"planet":"黄风岭·风穴深处","highlight":true,"context":{"plot":"黄风岭是被黄沙永久笼罩的荒芜之地。黄风大圣（原为灵吉菩萨的飞鼠）在《西游记》中用三昧神风差点使悟空失明。本作中，这片黄沙不是天灾——是黄风大圣以自身力量封印了一个更古老的存在，他的恶背后藏着一种沉重的牺牲。天命人到来打破了这脆弱的平衡。击败他后，深藏于黄风岭的另一个真相才逐渐浮现。","characters":"虎先锋（前置Boss）：黄风大圣的先锋大将，他的故事揭示了黄风岭内部的妖族矛盾。\n\n黄风大圣：飞鼠大王，外表暴君，实为被时间磨碎的守护者。他的战斗台词是全游戏最动人的Boss对白之一。\n\n鼠将（隐线）：黄风大圣之弟，侧面人物，他的故事解释了黄风岭黄沙的真正来源。","gameplay":"三昧神风全程影响视野（屏幕沙雾效果）。三阶段：常规风系出招→召唤沙柱AOE→飞离地面空中俯冲。核心：阶段三不要追击飞在空中的他，等他落地俯冲后的硬直窗口输出。腰间金链是弱点，可打断部分施法。"}},{"id":"spider_sisters","name":"蜘蛛精 — 盘丝洞迷局","nameEn":"Spider Sisters","folder":null,"progressPct":40,"storyGap":3,"planet":"盘丝岭·盘丝洞","highlight":false,"context":{"plot":"盘丝岭是第三回的前半段，一片被蛛网与幻术笼罩的妖异之地。蜘蛛精们是《西游记》中著名的女妖，本作将她们呈现为一群困在命运蛛网中的存在——既是猎手，也是囚徒。她们编织出迷幻的幻境，让天命人在真实与虚假之间迷失。与她们的战斗不只是体力的对抗，更是一场感知的考验：看清幻象背后的真相，才能找到破局之道。","characters":"蜘蛛精（众姐妹）：以幻术为武器，美艳而危险。她们的故事揭示了盘丝岭的另一层秘密——这片蛛网，也是某种意义上的牢笼。\n\n金池长老（关联线索）：盘丝岭深处隐藏着与金池长老相关的秘密，蜘蛛精的迷局是通往这段历史的前置钥匙。","gameplay":"蜘蛛精Boss战的核心是\"识破分身\"：她会制造多个分身在场中同时移动，只有攻击真身才能造成伤害。辨别真身方法：真身脚下有细微的阴影光效，分身略微透明。第二阶段召唤蛛网AOE，覆盖大面积地面——看到蛛网落点立刻跳离。推荐携带定身法术，可强制中断她的分身释放。"}},{"id":"huangmei","name":"黄眉大王 — 小雷音寺","nameEn":"Yellow-brow (Huangmei Duwang)","folder":null,"progressPct":47,"storyGap":3,"planet":"小雷音寺","highlight":true,"context":{"plot":"小雷音寺是假冒灵山的佛寺——外表庄严，内里全是谎言。黄眉大王是弥勒佛身边的扫塔力士，因偷了主人的法器（人种袋和金铙）下界为妖，自称如来，坐拥寺庙接受朝拜。他是游戏对宗教虚伪与权力崇拜最辛辣的讽刺。击败他后，藏于第三回深处关于菩提老祖的线索被解锁，暗示悟空最初的老师与天命人命运之间的隐秘联系。","characters":"黄眉大王：弥勒的扫塔力士，外表华贵庄严，实则是偷了主人宝贝的小跟班。他的笑容是游戏中最令人不安的存在。\n\n菩提老祖（隐线）：第三回深处的谜题核心，悟空的启蒙老师，也是天命人身份之谜的关键钥匙。","gameplay":"前半段难度峰值。三阶段：佛器攻击→金铙封印场（被卷入时快速挣脱按键）→人种袋召唤多个分身同场混战。金铙阶段最危险，一旦被封入需疯狂操作挣脱。火焰系克制他的部分护盾。保留变化术用于第三阶段分身混战期爆发。"}},{"id":"red_boy","name":"红孩儿 — 三昧真火","nameEn":"Red Boy","folder":null,"progressPct":70,"storyGap":4,"planet":"火焰山·红孩儿营地","highlight":true,"context":{"plot":"红孩儿是牛魔王之子，天生掌控三昧真火——这是一种连龙王之水都无法浇灭的神焰。在《西游记》原著中他曾以火攻重创孙悟空，最终被观音菩萨收服为善财童子。本作中，他是牛魔王决战前必须越过的一道关，但这场战斗远不止于此。红孩儿的愤怒与执拗折射出的，是牛魔王家族整体的悲剧：一个父亲的失职，一个儿子的孤独，火焰山上燃烧的不只是烈火，也是一段破碎的亲情。","characters":"红孩儿：牛魔王之子，年幼却强大，以三昧真火为武器。他的骄傲背后是渴望父亲认可的孤独小孩，这让他成为游戏中最令人心疼的反派之一。\n\n铁扇公主（关联背景）：红孩儿的母亲，她面对牛魔王堕落的态度将在击败红孩儿后逐渐展开。","gameplay":"红孩儿全程使用三昧真火，大量攻击附加火焰伤害并留下持续燃烧地板——尽量不站在红色地面上。三阶段：常规火拳连击→召唤火焰龙卷风→变身巨型火焰形态。第三阶段体型变大但攻击间隔也加长，等大招结束后的硬直窗口是最好的爆发时机。水系护符可减少所受火焰伤害，强烈推荐携带。"}},{"id":"bull_king","name":"牛魔王 — 第五回史诗决战","nameEn":"Bull King","folder":null,"progressPct":77,"storyGap":4,"planet":"火焰山·积雷山","highlight":true,"context":{"plot":"牛魔王是游戏体量最宏大、战斗最史诗的Boss。他曾是悟空结拜大哥中最强的一位，正直而豪迈。但在天庭封官许爵的腐蚀下，他逐渐迷失，抛弃了家庭与信念，最终成为一个为虚名而战的空壳。这场决战不是正义对邪恶，而是两个孤独强者的碰撞——一个迷失了的王，和一个正在寻找意义的天命人。他在战斗中的台词完整诉说了从志向凌云到自我消耗的堕落历程。","characters":"牛魔王：全游戏最具悲剧色彩的Boss。强大、孤独、迷茫。他的失败不是力量不够，而是他早已失去了战斗的意义。\n\n铁扇公主（战后）：她的选择是本章最令人动容的收尾，揭示了她对牛魔王感情的真实底色——爱恨交织，最终释然。\n\n红孩儿（前置Boss，70%处）：牛魔王之子，三昧真火攻击，先打红孩儿才能触发牛魔王决战。","gameplay":"四阶段史诗战斗，全游戏持续时间最长：阶段一真身牛魔加巨斧地震；阶段二愤怒形态速度大幅提升；阶段三变身巨型牛原型，体型是天命人十倍，AOE覆盖大半战场；阶段四天兵天将协战，牛魔被压制但反扑更猛。全程备3个大葫芦，阶段三绕到侧面攻击腿和腹部弱点，阶段四先消灭小兵防止夹击。"}},{"id":"six_eared_macaque","name":"六耳猕猴 — 最终真相","nameEn":"Six-Eared Macaque","folder":null,"progressPct":88,"storyGap":5,"planet":"灵山·真假之间","highlight":true,"context":{"plot":"这是整个游戏最震撼的剧情反转。六耳猕猴在游戏宇宙中承载着超出原著的深意。《西游记》真假美猴王是悟空内心矛盾的外化：自由与约束、本我与超我的决战。在黑神话的设定里，天命人一路追寻悟空踪迹，最终在灵山前明白——他追寻的不只是一段历史，而是悟空完整的那半个自己。六耳猕猴，就是那个被压抑、被否定、被遗忘的自由本性。这场战斗是自我与另一个自我的终极决战。","characters":"六耳猕猴：悟空的镜像，拥有几乎相同的外貌、武器和能力。他是整个游戏精神内核的具象化——自由的本性，被压抑后的反弹。\n\n天命人（主角本质揭示）：走到这里，玩家明白：天命人从未是传统意义上的主角，他是悟空意志的延续，是轮回的一环。\n\n悟空（两种结局）：普通结局是顺应轮回，真结局是打破。你的选择决定了这个故事的意义。","gameplay":"全游戏最高难度Boss之一。六耳猕猴会完整复制天命人的技能——你用什么他也会用。三阶段：常规金箍棒连击→读取你的出招习惯并反制→最终形态释放所有习得神通。核心策略：改变你全程惯用的打法，他会学习你的攻击模式。多用他较少见过的技能，保留最强化身和法术用于第三阶段爆发。"}}],"playerSentiment":{"steamScore":94,"source":"Steam 用户评测 & B站 & 微博 & Reddit","note":"国产3A首款里程碑作品，全球玩家高度认可，国内情怀加成明显","keywords":{"praise":["国产3A奇迹","画面世界顶级","Boss设计精彩","配乐荡气回肠","西游情怀满分","法术系统丰富","演出顶尖","悟空动作流畅","剧情隐喻深刻"],"criticism":["优化PC版偶有掉帧","女性角色稀少","支线引导不清","地图不够直观","后期难度跳跃"],"hot":["国产游戏崛起","六耳猕猴隐喻","真结局如何解锁","周星驰版大圣情怀","哪个Boss最难","黑神话vs艾尔登法环"]},"testimonials":[{"text":"第一次看到黄风大圣我以为我进了艺术展览，第二次看到我开始怀疑我是否应该去修行。","author":"Steam 评测","upvotes":8823},{"text":"做了二十年的老游戏玩家，没想到被国产游戏打到落泪。悟空，你打出去了。","author":"B站评论","upvotes":7621},{"text":"游戏告诉你：你是天命人。实际上：你会被同一个BOSS打死四十七次。两者并不矛盾。","author":"Steam 评测","upvotes":6204},{"text":"真结局看完后我坐在椅子上10分钟没说话。室友以为我出事了。","author":"微博用户","upvotes":4932}]}},{"id":"jedi_fo","name":"Star Wars Jedi: Fallen Order","titleMain":"Star Wars Jedi: Fallen Order","titleSub":"星球大战 绝地：陨落的武士团","short":"Fallen Order","genre":"动作冒险 · 魂类","currentPct":38,"developer":"Respawn Entertainment","year":2019,"steamAppId":1172380,"totalHoursMain":17,"totalHoursComplete":31,"bannerUrl":"assets/covers/jedi_fo-banner.jpg","posterUrl":"assets/covers/jedi_fo-poster.jpg","overview":{"tagline":"绝地之道，从废墟中重生","description":"Star Wars Jedi: Fallen Order 是 Respawn Entertainment 出品的单人动作冒险游戏，故事发生在《西斯的复仇》之后的黑暗年代。你扮演 Cal Kestis——一个在帝国猎杀中隐姓埋名的幸存绝地学徒——被迫重燃原力，踏上一段试图重建绝地秩序的旅途。游戏以魂系战斗为灵感，以星战宇宙的丰富视觉语言为背景，将探索、解谜和剑战融为一体。Cal 的成长弧线是全游戏的情感核心：一个逃避过去、对自己力量充满恐惧的年轻人，如何一步步面对自己，成为真正的绝地武士。","highlights":[{"icon":"⚡","text":"光剑战斗的极致手感：招架、闪避、原力推拉节奏感出色"},{"icon":"🌌","text":"星战氛围满分：每个星球都有独特的视觉风格和叙事密度"},{"icon":"🕵️","text":"第二黑暗兄弟会——Trilla 是近年最有深度的星战反派之一"},{"icon":"🔵","text":"结局抉择震撼：Cal 那一刻的决定定义了整部作品的主题"}]},"entryPoints":[{"progressPct":0,"label":"推荐起点：完整体验","reason":"Bracca 废料星球的开场是近年最好的游戏开场之一，Cal 身份揭露和逃亡序列直接抓住人心，不要跳过。"},{"progressPct":35,"label":"动作爽点入口","reason":"获得双刀之后战斗风格完全打开，招架-反击-原力连携已全部解锁，这是手感最好的入场时机。"},{"progressPct":65,"label":"剧情高潮直入","reason":"Trilla 真实身份揭露后故事进入情感高密度区间，Cal 的成长危机、BD-1 的秘密、圣所的真正含义开始层层展开。"}],"protagonistJourney":[{"progressPct":0,"event":"Bracca·身份暴露，逃亡开始","description":"Cal 在废料星球以工人身份苟活，一次本能反应暴露了他的原力能力，帝国的猎杀随即开始。","unlocks":["原力慢（Force Slow）","原力推（Force Push）","光剑基础连段"]},{"progressPct":18,"event":"Bogano·与 BD-1 相遇，使命确立","description":"遇见 BD-1，找到 Eno Cordova 的全息日志，Cal 第一次有了明确的使命：找到失落的绝地感应者名单。","unlocks":["原力拉（Force Pull）","壁跑强化","BD-1 探索辅助"]},{"progressPct":35,"event":"Dathomir 或 Zeffo·双刀与内心危机","description":"Cal 的光剑进化，战斗能力大幅提升。同时，Trilla 的压力和过去的创伤让 Cal 开始直面自己逃避已久的恐惧。","unlocks":["双刀形态（Split Saber）","原力闪避","高级格挡反击"]},{"progressPct":55,"event":"Kashyyyk 第二次·Saw 与盟友网络","description":"Cal 与抵抗军建立联系，意识到这场旅途不只是个人的成长，而是更大反抗叙事的一部分。","unlocks":["原力偏转（Force Deflect）","攀爬强化","光剑自定义解锁"]},{"progressPct":70,"event":"圣所·真相与崩溃","description":"BD-1 记忆完全解锁，Cordova 的真实决定揭晓。Cal 在最黑暗的时刻必须重新选择：继续还是放弃？","unlocks":["原力满强化","双手棍形态","全原力技能解锁"]},{"progressPct":88,"event":"最终决战·Cal 成为绝地","description":"对抗 Trilla、Vader、以及自己内心的恐惧。Cal 在这一刻真正完成了从学徒到绝地武士的转变。","unlocks":["原力巅峰状态","最终光剑形态","结局抉择"]}],"gameTheme":{"bg":"#07090f","bgCard":"#0d1220","accent":"#00b4ff","accent2":"#ff6b20","text":"#e6d5b4"},"saveDownload":{"url":"http://www.mediafire.com/file/obvapg7wvwuuk10/Jedi_Fallen_Order_Boss_Fight_Saves.zip/file","savePath":"C:/Users/{username}/Saved Games/Respawn/JediFallenOrder/","instructions":"1. 下载并解压 zip 文件\n2. 进入对应 Boss 战文件夹\n3. 将文件重命名为 Backup01.sav 和 SaveGame01.sav\n4. 复制到存档路径\n5. 启动游戏 → 读取存档"},"chapters":[{"id":0,"name":"序章：逃离 Bracca","planet":"Bracca","progressStart":0,"progressEnd":7,"hypeScore":7,"keyEvent":"Cal 逃离星球，与 Cere & Greez 相遇","plotDetail":"Cal Kestis 在废料星球 Bracca 以打捞工人身份苟活，帝国阴影下的幸存者之一。一次意外暴露了他的原力能力，帝国审判者随即追来。在混乱的逃亡中，Cal 遇见了前绝地武士 Cere Junda 和飞船船长 Greez——一段新的旅程就此强行开始。","playerGoals":"逃离帝国审判者的追捕 → 登上 Mantis 飞船离开 Bracca → 接受 Cere 的任务：重建绝地圣所","newCharacters":"Cal Kestis（主角，幸存绝地学徒）、BD-1（Cal 的忠实机器人搭档）、Cere Junda（前绝地武士，任务发起者）、Greez Dritus（飞船船长）、第二姐妹 Trilla（帝国审判者，主要反派）"},{"id":1,"name":"第一章：Bogano 地窖","planet":"Bogano","progressStart":7,"progressEnd":15,"hypeScore":5,"keyEvent":"结识 BD-1，Cordova 全息信息揭示任务","plotDetail":"Bogano 是一颗古老而宁静的星球，表面是辽阔的草原，地下深处藏着前绝地大师 Eno Cordova 遗留的地窖。Cal 在这里与 BD-1 正式结成搭档，并通过 Cordova 的全息日志得知任务核心：一份隐藏在宇宙某处的原力感应者名单，那是重建绝地秩序的唯一希望。","playerGoals":"探索 Bogano 地窖，解读 Cordova 的全息日志 → 与 BD-1 建立联系 → 确定下一个目标星球","newCharacters":"Eno Cordova（已故绝地大师，以全息日志形式出现，任务关键人物）"},{"id":2,"name":"第二章：Zeffo Eilram 墓","planet":"Zeffo","progressStart":15,"progressEnd":30,"hypeScore":6,"keyEvent":"重拾原力推力，再遇第二姐妹","plotDetail":"Zeffo 是一颗被帝国占领的考古星球，古代 Zeffo 人留下的风力神殿散落各处。Cal 深入 Eilram 墓穴重新习得原力推力，同时意识到帝国一直在跟踪他的行动路线。第二姐妹 Trilla 在这里真正展示了她的威胁——她不只是追杀者，她对绝地的仇恨背后藏着更深的故事。","playerGoals":"在帝国封锁下进入 Eilram 墓穴 → 解开古代 Zeffo 机关，重拾原力推力 → 与第二姐妹交手并脱身","newCharacters":"第二姐妹 Trilla（深度登场，仇恨绝地的审判者，与 Cere 的过去有联系）"},{"id":3,"name":"第三章：解救乌基族","planet":"Kashyyyk","progressStart":30,"progressEnd":46,"hypeScore":7,"keyEvent":"遇见 Saw Gerrera，攀登源树，击败第九姐妹","plotDetail":"Kashyyyk 是乌基族（Wookiee）的家园，也是帝国奴役计划的重灾区。Cal 来到这片参天巨树与工业污染并存的星球，与传奇反叛军领袖 Saw Gerrera 短暂同行，攀登神圣源树，最终在树顶击败了残暴的第九姐妹。这一章拓展了星战宇宙的反叛军叙事，也让 Cal 第一次感受到比个人任务更宏观的斗争。","playerGoals":"接触 Saw Gerrera 的抵抗力量 → 攀登源树，解放被帝国奴役的乌基族 → 击败第九姐妹，保住生路","newCharacters":"Saw Gerrera（反叛军领袖，星战经典角色）、第九姐妹（帝国审判者，力量型对手）"},{"id":4,"name":"第四章：Miktrull 墓穴","planet":"Dathomir / Zeffo","progressStart":46,"progressEnd":62,"hypeScore":8,"keyEvent":"夜姐妹登场，双刃光剑解锁，Cere 的秘密","plotDetail":"这一章在两颗截然不同的星球间切换：神秘黑暗的 Dathomir 和古老考古的 Zeffo。Dathomir 夜姐妹巫术文化的登场为游戏增添了前所未有的黑暗气质；而 Cere 长期回避的秘密在这章逐渐浮出——她曾经背叛过一个绝地，那个绝地就是 Trilla。Cal 的光剑在这章进化为双刃形态，战斗风格彻底改变。","playerGoals":"进入 Miktrull 墓穴取得第二枚球体 → 在 Dathomir 面对夜姐妹的黑暗原力 → 了解 Cere 与 Trilla 之间的痛苦过去","newCharacters":"Merrin（Dathomir 夜姐妹，起初为敌）、Taron Malicos（堕落的前绝地大师）、Cere 的过去（完整揭露）"},{"id":5,"name":"第五章：Ilum & Dathomir","planet":"Ilum / Dathomir","progressStart":62,"progressEnd":80,"hypeScore":9,"keyEvent":"打造新光剑，击败 Malicos，Merrin 加入","plotDetail":"Ilum 是绝地圣地，Cal 在这里以凛冽的冰晶重新打造了属于自己的光剑——这是一个绝地成年礼的完成。随后回到 Dathomir，Cal 必须击败已完全堕落的 Malicos，并赢得 Merrin 的信任。她最终选择加入 Mantis 的旅程，为最后的决战带来关键力量。","playerGoals":"在 Ilum 圣地重塑光剑，完成属于自己的武器 → 在 Dathomir 决战堕落大师 Malicos → 说服 Merrin 放下仇恨，加入团队","newCharacters":"Merrin（转变为盟友，夜姐妹巫术战士）"},{"id":6,"name":"第六章：审判者要塞","planet":"Nur","progressStart":80,"progressEnd":100,"hypeScore":10,"keyEvent":"击败第二姐妹，Darth Vader 追杀，毁掉 Holocron","plotDetail":"审判者要塞深藏于 Nur 的海底——帝国残酷的绝地猎杀机器的核心所在。Cal 在这里面对 Trilla 的最终决战，而 Cere 终于在关键时刻补全了她对学徒的亏欠。当 Holocron 就在手中，Darth Vader 的出现改变了一切。Cal 做出了整部游戏最重要的抉择：销毁名单，让那些孩子永远不被帝国找到。这个决定的重量，是整个故事的精神总结。","playerGoals":"突入审判者要塞，击败第二姐妹 Trilla → 在 Darth Vader 的追杀下活命脱逃 → 面对最终抉择：使用还是销毁 Holocron","newCharacters":"Darth Vader（终极威胁登场，是对绝地力量天花板的现实展示）"}],"hypePeaks":[{"progressPct":3,"label":"逃离 Bracca","score":7,"color":"#f97316"},{"progressPct":13,"label":"第二姐妹初遇","score":6,"color":"#ef4444"},{"progressPct":27,"label":"Zeffo 对决","score":7,"color":"#ef4444"},{"progressPct":44,"label":"击败第九姐妹","score":8,"color":"#f97316"},{"progressPct":55,"label":"Cere 秘密揭露","score":8,"color":"#a855f7"},{"progressPct":65,"label":"打造新光剑","score":6,"color":"#eab308"},{"progressPct":73,"label":"Malicos 终局","score":8,"color":"#a855f7"},{"progressPct":88,"label":"击败第二姐妹","score":9,"color":"#ef4444"},{"progressPct":93,"label":"Vader 追杀","score":10,"color":"#ef4444"},{"progressPct":98,"label":"毁掉 Holocron","score":8,"color":"#a855f7"}],"achievements":[{"steamId":"ACH_STORY_MANTIS","name":"The Mantis","progressPct":10},{"steamId":"ACH_STORY_BOGANO","name":"A Long Time Ago","progressPct":13},{"steamId":"ACH_STORY_EILRAM","name":"The Obstacle Is the Way","progressPct":28},{"steamId":"ACH_STORY_WOOKIE","name":"Happy Go Wookiee","progressPct":43},{"steamId":"ACH_STORY_NINTH","name":"Her Name Was Masana Tide","progressPct":44},{"steamId":"ACH_STORY_MIKTRULL","name":"Everything Is Connected","progressPct":57},{"steamId":"ACH_STORY_SABER","name":"For A More Civilized Age","progressPct":66},{"steamId":"ACH_STORY_TRILLA","name":"I Knew He Was No Good","progressPct":78},{"steamId":"ACH_STORY_VAULT","name":"The Holocron Awaits","progressPct":85},{"steamId":"ACH_STORY_END","name":"Trust Only In the Force","progressPct":100}],"bossSaves":[{"id":"trilla_bogano","name":"第二姐妹 - Bogano 初遇","nameEn":"Second Sister - Bogano","folder":"Trilla fight bogano","progressPct":13,"storyGap":1,"planet":"Bogano","highlight":false,"context":{"plot":"Cal Kestis 是六十六号令（Order 66）的幸存帕达旺，隐姓埋名在废船场 Bracca 打工。一次救人时意外暴露原力，随即遭帝国追杀。前绝地骑士 Cere Junda 和飞行员 Greez 带他逃走，登上曼蒂斯号飞船。根据绝地大师 Eno Cordova 的线索，一行人前往 Bogano 古星寻找一枚全息晶体（Holocron），其中记载了全银河原力敏感儿童的名单。Cal 找到了 Cordova 的机器人 BD-1，正当他靠近地窖时，帝国第二姐妹赶到拦截。","characters":"Cal Kestis：主角，前帕达旺，师从 Jaro Tapal（六十六号令中牺牲）。被迫压抑原力多年，战斗能力尚未完全恢复。\n\nCere Junda：Cal 的新导师，前绝地骑士。曾在帝国的折磨下主动切断与原力的联系，内心满是愧疚。\n\nBD-1：Cal 的机器人搭档，携带 Cordova 遗留的全息记忆碎片，会在关键地点播放线索。\n\n第二姐妹（Trilla Suduri）：主要反派，帝国审讯官，擅用双向光剑。她的真实身份与 Cere 有极深的悲剧联系（后期揭晓）。","gameplay":"初期存档，Cal 能力极有限：光剑基础单刃，原力仅有 BD-1 辅助的时缓（Force Slow），真实原力推力尚未恢复。这场遭遇是剧情触发战——打到特定血量后自动过场，无需真正击败。重点练习格挡（Parry）的精准时机。"}},{"id":"atst_zeffo1","name":"AT-ST 第一战 - Zeffo","nameEn":"First AT-ST - Zeffo","folder":"First ATST fight","progressPct":21,"storyGap":1,"planet":"Zeffo","highlight":false,"context":{"plot":"Cal 离开 Bogano 前往 Zeffo，追踪 Cordova 的足迹寻找 Eilram 墓穴。Zeffo 是古老种族泽弗人的故乡，他们对原力的研究是绝地哲学的早期来源之一。帝国已占领这颗星球，大规模掘墓盗取古代文物。Cal 在前往墓穴途中遭遇了帝国 AT-ST 步行机甲的拦截。","characters":"Cal：开始逐步恢复原力，与 BD-1 的配合越来越熟练。\n\nCere（飞船通讯）：提供背景信息和指导，自身不使用原力。","gameplay":"Cal 已恢复原力推力（Force Push），可将敌人击飞或推入悬崖。AT-ST 膝关节是弱点——Force Push 推击膝盖使其倒地，随后攻击驾驶舱顶部。利用周围掩体规避炮击，保持移动。"}},{"id":"second_sister_zeffo","name":"第二姐妹 - Zeffo 对决","nameEn":"Second Sister - Zeffo","folder":"First second sister fight on zeffo","progressPct":27,"storyGap":2,"planet":"Zeffo","highlight":true,"context":{"plot":"Cal 完成 Eilram 墓穴探索，获得 Cordova 全息晶体的第一块线索。BD-1 播放的 Cordova 记忆碎片揭示了更多任务背景：Cordova 曾走遍银河追踪原力敏感儿童下落，最终将名单藏入 Bogano 地窖。第二姐妹在帝国营地附近设伏，这次她认真了——这场战斗比 Bogano 初遇激烈得多，是 Cal 第一次真正意义上的绝地决斗。","characters":"第二姐妹：开始展现更复杂的个性，不仅是杀手，还会心理施压。她掌握了关于 Cal 和 Cere 的某些秘密信息，蓄意利用。\n\nCal：原力推力解锁后第一次真正意义上的绝地决斗，开始明白逃跑只是推迟问题，不是解决问题。","gameplay":"Cal 拥有：光剑基础技能 + Force Push + Force Slow。第二姐妹会主动拉拽 Cal 的光剑并反击——看到她的抓取动作时立即闪避。成功弹反（Parry）可大幅削减其体力条，练习弹反节奏是关键。"}},{"id":"rooftop_kashyyyk","name":"屋顶突袭 - Kashyyyk","nameEn":"Rooftop Fight - Kashyyyk","folder":"Rooftop fight kashyyyk","progressPct":35,"storyGap":2,"planet":"Kashyyyk","highlight":false,"context":{"plot":"Cal 一行接到 Saw Gerrera 的信号，前往乌基族家园 Kashyyyk。帝国在此建立精炼厂，强迫乌基族做奴隶劳工。Cal 与反抗军联合行动，协助乌基族对抗帝国。乘坐电梯抵达高处后，帝国突击队和一架 AT-ST 在屋顶设下伏击。这是一场高空平台激战。","characters":"Saw Gerrera：极端的反帝国战士，手段激进（侠盗一号角色）。他掌握乌基族老酋长 Tarfful 的下落，后者曾与 Yoda 并肩作战，可能知道更多 Cordova 任务的线索。\n\nTarfful：乌基族老酋长，正被帝国秘密关押，是 Cal 来 Kashyyyk 的核心目的。","gameplay":"Cal 此时应已解锁墙面跑（Wall Run）。AT-ST 打法：Force Push 推倒膝盖后趁它恢复时消灭周围士兵，再补第二轮推击。注意脚下高台边缘，别被敌人推落。"}},{"id":"bounty_arena","name":"悬赏猎人竞技场","nameEn":"Bounty Hunter Arena","folder":"Bounty Hunter Arena Fight","progressPct":41,"storyGap":1,"planet":"未知星球","highlight":false,"context":{"plot":"Haxion Brood 是受犯罪头目 Sorc Tormo 雇佣的悬赏猎人组织，一直追踪 Cal。在某次探索中 Cal 遭到捕捉，被押送到 Sorc Tormo 的私人竞技场，在欢呼的观众面前充当娱乐工具。他必须打穿一波又一波的杀手和机甲才能逃脱。这条支线与主线关系不大，但战斗本身设计精彩、肾上腺素十足。","characters":"Sorc Tormo：贪婪的犯罪头目，把杀戮当作娱乐，非帝国官方势力。\n\nHaxion Brood 佣兵：涵盖多种类型——普通雇佣兵、机甲战士、远程狙击手，每波都有新的战术挑战。","gameplay":"连续多波混战：普通佣兵 - 机甲战士 - 精英佣兵。充分利用 Force Push 清场，保持持续移动不要站原地。这关是练习 Cal 综合连招的绝佳场合，尝试各种打法切换。"}},{"id":"ninth_sister","name":"第九姐妹 - 源树之巅","nameEn":"Ninth Sister - Origin Tree","folder":"Ninth Sister Fight","progressPct":44,"storyGap":3,"planet":"Kashyyyk","highlight":true,"context":{"plot":"Cal 攀登 Kashyyyk 源树（Origin Tree）顶端，寻找被帝国关押的乌基族老酋长 Tarfful。就在快到达顶部时，第九姐妹（Ninth Sister，另一位帝国审讯官，与第二姐妹完全不同的人物）从空中俯冲截住了 Cal。第九姐妹的任务是从 Cal 脑中强行读取所有绝地相关信息——审讯官拥有侵入他人心灵的原力能力。这是 Cal 迄今遭遇的最强战斗对手，也是他第一次真正以绝地身份单独迎战帝国审讯官的正面考验。","characters":"第九姐妹（Masana Tide）：身材高大的 Dowutin 种族，使用巨型双向光剑，力量型打法。曾经也是绝地骑士，被帝国俘虏折磨后沦为审讯官。\n\nTarfful（战斗后出现）：他给了 Cal 下一步旅程的关键线索，指引前往 Dathomir 和 Zeffo 的新区域。\n\nCal：这场胜利是成长弧线上的重要里程碑——他开始真正相信自己有能力守护他人。","gameplay":"中期重要 Boss 战，分两阶段。阶段一：她用双刃光剑攻击，重击有明显蓄力预警，看到红色闪光立即闪避（无法弹反）。阶段二（断手后）：变得更加狂暴，出招更快。利用树顶平台保持机动，精准弹反普通攻击积累破防（Stagger），破防后集中输出。"}},{"id":"gorgara","name":"Gorgara - Dathomir 峭壁巨兽","nameEn":"Gorgara - Dathomir","folder":"Gorgara Fight","progressPct":50,"storyGap":2,"planet":"Dathomir","highlight":false,"context":{"plot":"Cal 抵达 Dathomir——黑暗星球，夜姐妹（Nightsisters）的古老故土。夜姐妹是绿色魔法巫女战士，曾在克隆人战争中几乎被灭族（被葛里弗斯将军屠杀）。Cal 在 Dathomir 峭壁攀爬时，短暂遭遇了年轻的夜姐妹幸存者 Merrin——她对 Cal 充满敌意，因为有人告诉她是绝地骑士杀死了她的族人（这是谎言）。Gorgara 是 Dathomir 的巨型翼兽，将 Cal 视为入侵者，从黑暗中俯冲而来。","characters":"Merrin：后期重要队友，目前是敌对状态。年轻、孤独、充满仇恨，被欺骗多年。她与 Cal 的关系弧线是游戏最动人的情感线之一。\n\nTaron Malicos（即将登场）：一个自称绝地的神秘陌生人曾短暂帮助 Cal。实际上他是六十六号令后精神崩溃、堕入黑暗面的前绝地大师，一直在操控 Merrin 的仇恨为己所用。","gameplay":"独特的巨型 Boss 战：Cal 在悬崖峭壁上攀爬，同时攻击悬停空中的 Gorgara 的弱点（翅膀薄膜和爪部）。关键是利用 BD-1 提示的攻击窗口。更考验空间感和时机把握，而非单纯格挡。"}},{"id":"platform_ilum","name":"Ilum 新光剑初阵","nameEn":"Platform Fight - Ilum","folder":"Platform stormtroopers fight with new lightsaber","progressPct":65,"storyGap":4,"planet":"Ilum","highlight":false,"context":{"plot":"经历了 Zeffo、Kashyyyk、Dathomir 的重重艰辛后，Cere 终于吐露了她最深的秘密：六十六号令时，她被帝国俘虏，在无尽折磨下崩溃，亲口说出了自己帕达旺的藏身处——而那个被她出卖的帕达旺，后来成为了第二姐妹。这个真相深深震撼了整个团队的信任关系。Cal 随后只身前往神圣的 Ilum——曾是绝地最重要的圣地，帕达旺们在此打造人生中第一把光剑。如今帝国已将 Ilum 变成采矿场，大规模开采凯伯晶体。Cal 完成了迟来的成年礼：在冰封水晶洞穴中打造了新的光剑。刚走出洞穴，帝国士兵就在外面等候。","characters":"Cal：重要成长节点——打造光剑象征他正式接受自己绝地骑士的身份和使命。\n\nCere Junda：刚坦承了最深的罪与愧疚，正试图重建对原力的连接，她的成长弧线接近高潮。\n\n帝国：为何大规模开采 Ilum 的凯伯晶体？（为后续星战宇宙埋下重要伏笔——终极武器的原料来源）","gameplay":"Cal 打造了新光剑，可选择武器形态：单刃 / 双刃 / 双持（取决于技能树解锁进度）。技能树此时相当丰富，是中后期存档。双刃旋转攻击（Spin Attack）清理普通士兵效率极高——享受新武器的爽快感！"}},{"id":"double_atst_ilum","name":"双 AT-ST - 撤离 Ilum","nameEn":"Double AT-ST - Ilum","folder":"Ilum Double AT-ST Fight","progressPct":68,"storyGap":4,"planet":"Ilum","highlight":false,"context":{"plot":"Cal 在 Ilum 打造完新光剑，正准备撤离，帝国已封锁所有出口。在逃往曼蒂斯号飞船的路上，两架 AT-ST 同时拦截。这是对 Cal 新力量的第一次真实考验——带着全新的光剑和技能，他需要同时应对两台重型步行机甲。","characters":"与上一关（Ilum 新光剑初阵）相同，无新角色登场。纯粹的战斗挑战——也是整个游戏 AT-ST 战斗的终极版。","gameplay":"双 AT-ST 同时登场！核心策略：永远只让一台对准你，用地形遮挡另一台的炮击视线。Force Push 推倒一台膝盖，趁它起身时转向另一台。两台交替倒地，各个击破。新双刃光剑的旋转攻击可打断大多数普通攻击动作。绝不要站在两台机甲的交叉火力线上。"}},{"id":"taron_malicos","name":"Taron Malicos - 堕落的大师","nameEn":"Taron Malicos - Dathomir","folder":"Taron Malicos Fight","progressPct":73,"storyGap":4,"planet":"Dathomir","highlight":true,"context":{"plot":"这是全游戏情感最丰富的 Boss 战之一。Taron Malicos 曾是受人尊敬的绝地大师。六十六号令时他困在 Dathomir，目睹手下克隆士兵叛变、同僚被屠杀，信仰土崩瓦解。他在绝望中研究 Dathomir 黑暗原力，走火入魔。为了稳固统治地位，他欺骗了年轻夜姐妹幸存者 Merrin：谎称是绝地骑士杀死了她的族人（事实上是他自己的克隆士兵所为），借此操控她的仇恨和魔法。Cal 揭露了 Malicos 的谎言，Merrin 终于看清真相。她用夜姐妹魔法压制住 Malicos，让 Cal 正面决战这位堕落的大师。战斗结束后，Merrin 正式加入曼蒂斯号。","characters":"Taron Malicos：强大的前绝地大师，使用双刃光剑，擅长操控 Dathomir 岩石进行大范围攻击。他代表了一种深刻的警示：绝望和孤立如何将一个正义之人推向黑暗。\n\nMerrin（关键转变）：本场战斗中从敌人变为盟友。她的魔法能力（传送、结界、束缚）是战斗机制的重要部分，也是她日后成为团队核心成员的前提。\n\nCere：仍在船上，她与原力的重新连接越来越深——为最终章决战做出铺垫。","gameplay":"高难度两阶段 Boss 战。阶段一：他轮流使用远程岩石轰炸和近战光剑连击。岩石攻击前有明显举手预警，快速闪避。近战时专注弹反积累破防。阶段二（Merrin 介入后）：Merrin 的魔法会周期性将 Malicos 固定——这是集中输出的窗口，不要浪费！用重击和所有原力技能在固定期间最大化伤害。Cal 此时技能树接近完整，放开手脚发挥一切。"}},{"id":"fortress_arena","name":"审讯官要塞 - 竞技场","nameEn":"Inquisitor Fortress Arena - Nur","folder":"Inquisitor Fortress Arena fight","progressPct":85,"storyGap":4,"planet":"Nur","highlight":false,"context":{"plot":"Cal 携全员突袭位于海洋星球 Nur 的帝国审讯官要塞，目标是夺回全息晶体（Holocron）。要塞戒备森严，Cal 被捕后被投入内部训练竞技场——这里设计之初就是为了淘汰（杀死）任何试图闯入的入侵者。他必须在多波精英敌人的围攻中突出重围。Cere 走的是另一条路线，独自面对她与第二姐妹（昔日帕达旺）之间悬而未决的过去。","characters":"Cal、Cere、Greez、Merrin、BD-1：全员在场，各有各的战线。\n\n帝国精锐：驻扎着帝国最精锐的战士，包括净化兵（Purge Troopers，专门训练对抗绝地的特种部队）和持光剑的帝国哨兵。\n\nCere 的成长弧高潮：她即将面对自己一生中最艰难的选择——能否重新接受原力，并正视她与 Trilla 之间未了的宿命。","gameplay":"精英混战，Cal 处于全游戏最强状态，技能树接近满载。净化兵（Purge Troopers）：擅长格挡和反击，等他们出手后弹反，电棍攻击弹反后他们会被自己武器电晕。帝国哨兵：持光剑，会主动弹反你的攻击，注意节奏变化。Force Pull 把远程敌人拉近处理，避免腹背受敌。双刃旋转清场多个近身敌人时效率最高。"}},{"id":"trilla_final","name":"第二姐妹终局 + Vader 追杀","nameEn":"Second Sister Final + Vader Chase","folder":"Trilla Final Boss Fight","progressPct":92,"storyGap":5,"planet":"Nur","highlight":true,"context":{"plot":"游戏最高潮，也是整个故事的情感核心。Cal 终于在要塞深处找到第二姐妹（Trilla Suduri）。在战斗中，Cal 通过原力共感触碰到 Trilla 内心深处的记忆：她原本是 Cere 最珍视的帕达旺，两人感情深厚如母女。六十六号令后她被帝国抓获，经历了无尽折磨和漫长等待——而她等待的救援，始终没来。Cere 在极度痛苦下说出了她的藏身处。就在 Trilla 内心深处那个被压抑已久的真实自我短暂浮现的瞬间，Darth Vader 出现了。他用原力扼住 Trilla 的咽喉，在所有人面前冷酷地处决了她。然后，Vader 转向 Cal 一行。这位几乎不可战胜的黑暗领主追杀着众人穿越正在进水的要塞。Cal 只能拼命逃跑。最终众人狼狈逃脱。Cal 手握全息晶体，做出了最后的选择：摧毁晶体——不让任何人有机会用这份名单找到那些孩子。","characters":"Trilla Suduri（第二姐妹）：从反派到悲剧人物。她的一生是被时代、战争、信任的人碾碎的缩影。她的结局是全游戏最令人心碎的瞬间之一。\n\nCere Junda：面对她一生最沉重的罪与愧疚。她能否原谅自己？Trilla 是否有机会原谅她？这个问题在最后一刻被 Vader 永远封住了。\n\nDarth Vader：仅登场数分钟，却是整个游戏最令人难忘的存在。他不是传统意义上的最终 Boss——他是一场灾难，在昏暗走廊中几乎就是死亡的化身。\n\nCal Kestis：成长弧线完成。从一个躲藏的幸存者，成长为有担当的绝地骑士。他的担当不是力量，而是放弃力量——选择保护而非复仇。","gameplay":"分两段体验。【第二姐妹终战】：她速度和连招达到全游戏巅峰，大量使用原力闪现和混乱连击。专注弹反节奏，不要贪刀。等她喘息或读条时果断反击。精准弹反积累破防后用最强连招输出。【Vader 追逐关卡】：这不是战斗，是纯粹的逃跑。不要尝试攻击 Vader——他会将一切格挡或无视。持续向前跑，Vader 会用原力扭曲和封锁地形，BD-1 会高亮新的路径。用原力推和墙面跑通过新打开的路线。享受这段星战历史上最经典的 Vader 登场演出之一。"}}],"playerSentiment":{"steamScore":87,"source":"Steam 用户评测 & Metacritic & Reddit","note":"EA发行商负面情绪影响了早期口碑，游戏本体高度认可","keywords":{"praise":["战斗系统精彩","Vader登场封神","剧情感情充沛","Cere角色深度","BD-1萌翻了","关卡设计精密","Merrin加入惊喜","星战情怀满满"],"criticism":["EA来者不善","加载时间过长","探索有些迷路","Boss难度不均","无周期自动存档"],"hot":["Vader走廊最佳时刻","Trilla悲剧结局","Cere的秘密","结局毁掉Holocron对吗","BD-1最佳机器人伴侣"]},"testimonials":[{"text":"花了17小时终于通关，然后Vader走廊30秒让我觉得钱花得值。","author":"Steam 评测","upvotes":4821},{"text":"BD-1是我2019年最喜欢的伴侣，不接受反驳。包括我的猫。","author":"Reddit r/FallenOrder","upvotes":3204},{"text":"游戏叫\"Fallen Order\"，但我在悬崖上摔下去的次数足以给它改名叫\"Falling Order\"。","author":"Steam 评测","upvotes":2967},{"text":"Trilla的结局让我在凌晨2点对着屏幕发呆了5分钟。Vader一出现我直接站起来了。","author":"Metacritic 用户评测","upvotes":1893}]}},{"id":"last_of_us_1","name":"The Last of Us Part I","titleMain":"The Last of Us Part I","titleSub":"最后生还者 第一部","short":"TLOU I","genre":"动作冒险","currentPct":22,"developer":"Naughty Dog","year":2023,"steamAppId":1888930,"totalHoursMain":15,"posterUrl":"assets/covers/last_of_us_1-poster.jpg","bannerUrl":"assets/covers/last_of_us_1-banner.jpg","gameTheme":{"bg":"#160e06","bgCard":"#1e1408","accent":"#b8820d","accent2":"#5c3600","text":"#e0cfa0"},"overview":{"tagline":"末日之后，人性才是真正的荒野","description":"真菌大流行摧毁人类文明二十年后，冷酷走私客乔尔受命护送免疫少女艾莉横跨废土美国。这不只是一场求生之旅——而是一段让你在游戏结束后久久凝视天花板的父女羁绊。《美国末日》重制版以全新画质重塑了这部现代游戏史上最重要的叙事之作。","highlights":[{"icon":"🎭","text":"BAFTA 年度最佳游戏"},{"icon":"🍄","text":"真菌感染·克利克人·僵尸"},{"icon":"💔","text":"乔尔与艾莉的父女羁绊"},{"icon":"⚡","text":"物资匮乏·偷袭与迂回战斗"}]},"entryPoints":[{"progressPct":0,"label":"序章·萨拉之夜","reason":"灾难爆发第一夜的情感震撼是整部游戏的情感基石，必须亲历"},{"progressPct":35,"label":"匹兹堡·亨利与萨姆","reason":"乔尔艾莉配合逐渐默契，兄弟情副线同步展开，战斗+剧情节奏最稳"},{"progressPct":70,"label":"冬季·艾莉独角戏","reason":"全游戏最黑暗也最震撼的章节，艾莉独自面对大卫的真相，彻底颠覆玩家视角"}],"protagonistJourney":[{"progressPct":3,"event":"灾难爆发之夜，萨拉离世","description":"乔尔在感染爆发的混乱中失去女儿萨拉，从此将内心封锁，成为冷酷的走私客。","unlocks":["乔尔·核心动机建立","末日世界观揭示"]},{"progressPct":15,"event":"接受护送任务，泰丝牺牲","description":"老友泰丝以生命为代价守住了艾莉的秘密，乔尔被迫独自肩负护送任务。","unlocks":["与艾莉同行","免疫谜题埋下伏笔"]},{"progressPct":22,"event":"比尔的镇子，战胜膨胀者","description":"在比尔的废镇取得交通工具，乔尔第一次允许艾莉在危险中证明自己的价值。","unlocks":["艾莉战斗协同解锁","获得载具"]},{"progressPct":48,"event":"亨利与萨姆——被感染的孩子","description":"亨利兄弟与乔尔艾莉短暂并肩，但萨姆的感染以悲剧结束，乔尔再次压下情感。","unlocks":["信任代价主题","艾莉情感成长"]},{"progressPct":62,"event":"大学遭袭，乔尔身受重伤","description":"大学任务以乔尔重伤告终，艾莉第一次真正需要反过来保护他。角色关系完成逆转。","unlocks":["艾莉成为临时主角","角色动态逆转"]},{"progressPct":85,"event":"艾莉击败大卫，最深的黑暗","description":"艾莉独自面对食人领袖大卫并亲手结束，这一刻她失去了最后的纯真。乔尔的呼唤将她从边缘拉回。","unlocks":["艾莉人格蜕变完成","乔尔真情流露"]},{"progressPct":97,"event":"医院·乔尔的抉择","description":"乔尔为救艾莉摧毁了萤火虫制造疫苗的唯一机会，然后对艾莉撒了谎。这个谎言将是续作一切的根源。","unlocks":["结局道德争议","Part II 伏笔完全埋下"]}],"hypePeaks":[{"progressPct":4,"label":"萨拉之死","score":10,"color":"#ef4444"},{"progressPct":14,"label":"泰丝牺牲","score":7,"color":"#f97316"},{"progressPct":22,"label":"膨胀者·比尔","score":7,"color":"#f97316"},{"progressPct":38,"label":"匹兹堡桥逃亡","score":8,"color":"#ef4444"},{"progressPct":48,"label":"萨姆感染之夜","score":9,"color":"#ef4444"},{"progressPct":62,"label":"乔尔重伤坠落","score":8,"color":"#f97316"},{"progressPct":75,"label":"大卫真面目揭露","score":8,"color":"#a855f7"},{"progressPct":85,"label":"艾莉杀死大卫","score":10,"color":"#ef4444"},{"progressPct":97,"label":"乔尔的抉择·谎言","score":10,"color":"#ef4444"}],"bossSaves":[{"id":"bloater_bill","name":"膨胀者 — 比尔的学校体育馆","planet":"林肯镇","progressPct":22,"storyGap":2,"highlight":true,"context":{"plot":"乔尔与艾莉在比尔帮助下试图取得车辆零件，路过废弃高中时触发了感染者巢穴。膨胀者（Bloater）是游戏首个真正意义上的\"Boss级\"感染者，真菌几乎完全覆盖其身体，刀枪难入。","characters":"膨胀者：完全真菌化的末期感染者，可投掷真菌孢子爆弹并抓住人类直接断颈。其装甲需要特殊手段击破。比尔：悲观主义的末日幸存者，守护着自己划定的\"领地\"，独自活了二十年。","gameplay":"优先用燃烧瓶或汽油弹烧掉装甲块，再用猎枪近距离爆头。全程保持移动，绝对不能被它抓住——秒杀。准备好弓箭爆头清掉周围的普通感染者，不要被围住。","save":"本关卡无社区存档包。建议在进入体育馆前手动存档，可重复挑战熟悉战斗机制。"}},{"id":"bloater_pittsburgh","name":"膨胀者 — 匹兹堡下水道","planet":"匹兹堡","progressPct":40,"storyGap":3,"highlight":false,"context":{"plot":"乔尔、艾莉与亨利兄弟在匹兹堡地下水道中试图逃出生天，下水道深处封锁着另一个膨胀者。这一关节奏更紧张——逃跑是选项，但有时必须正面应对。","characters":"亨利：为保护弟弟萨姆不惜一切的哥哥，曾有过难以启齿的过去。萨姆：童年在末日中被剥夺的少年，与艾莉产生了深厚的友谊，却命运多舛。","gameplay":"合理分配燃烧瓶与弓箭，利用狭窄通道引导膨胀者。有时跑过它不战斗是更优解——保存弹药给后续更难的战斗。","save":"本关卡无社区存档包。进下水道前自动存档，在菜单手动另存一格以便重试。"}},{"id":"david_fight","name":"大卫 — 冬季小屋决战","planet":"科罗拉多山区","progressPct":85,"storyGap":4,"highlight":true,"context":{"plot":"全游戏最黑暗的时刻。艾莉独自被大卫追杀于燃烧的餐厅之中。大卫表面是末日宗教领袖，实际上是食人幸存者团伙的头目，对艾莉图谋不轨。艾莉必须在黑烟弥漫的空间中击败他——或者更确切地说，终结他。","characters":"大卫：游戏最令人不寒而栗的人类反派。他的危险不来自武器，而来自语言和操控。被艾莉击败后，她的内心也留下了无法磨灭的创伤。艾莉：这一幕是她成年礼，代价是永远失去某种纯真。","gameplay":"这是纯艾莉视角的潜行+决斗关卡。利用浓烟遮挡视线进行偷袭。保持移动，用砍刀近战。大卫有近战攻击会抓住艾莉——疯狂按提示键挣脱。不要让他靠近超过两次。","save":"本关卡无社区存档包。餐厅门口会自动存档，确保不要覆盖之前的进度。"}},{"id":"hospital_ending","name":"医院突袭 — 乔尔的最终抉择","planet":"盐湖城萤火虫医院","progressPct":96,"storyGap":5,"highlight":true,"context":{"plot":"乔尔只身闯入萤火虫医院，击败大批守卫，在手术室最后关头救下即将被摘除脑部的艾莉。最后，他枪杀了萤火虫领袖玛琳——世界治愈疫苗的唯一机会就此断绝。他对艾莉谎称萤火虫放弃了研究。这个谎言，埋下了《Part II》所有悲剧的种子。","characters":"玛琳：萤火虫领袖，艾莉亡母的老友。乔尔：在这一刻彻底从\"走私客\"变成了\"父亲\"——用全人类的未来换回了一个人。艾莉：此刻还不知道真相，对于那个谎言，她最终会去追问。","gameplay":"医院守卫战：利用掩体弹反，弹药充足。最终与玛琳的对话是纯叙事，无需战斗。请放慢脚步，充分体验最后的过场动画——这是游戏史上争议最大、也最令人心碎的结局之一。","save":"本关卡无社区存档包。到达医院会自动存档，建议事先手动另存一格，方便重温最终抉择。"}}],"chapters":[{"id":0,"name":"序章·萨拉之夜","planet":"德克萨斯州奥斯汀","progressStart":0,"progressEnd":5,"hypeScore":10,"keyEvent":"真菌爆发第一夜，乔尔失去女儿萨拉","plotDetail":"游戏从乔尔女儿萨拉的视角开始——邻居们的异常举动、深夜的逃亡、公路上的混乱，最终以萨拉在乔尔怀中死去告终。这段序章以最快速度建立起乔尔最深的伤痛，也是理解他后续一切行为的关键。","playerGoals":"体验叙事，无特定目标——跟着萨拉走，感受世界崩塌","newCharacters":"乔尔（主角）、萨拉（女儿）、托米（乔尔弟弟）"},{"id":1,"name":"检疫区·波士顿","planet":"马萨诸塞州波士顿","progressStart":5,"progressEnd":18,"hypeScore":7,"keyEvent":"乔尔与泰丝接下护送任务，泰丝感染后自我牺牲","plotDetail":"二十年后，乔尔是波士顿检疫区的走私客。萤火虫给他们一辆车作为报酬——代价是把艾莉送出城。泰丝感染后选择引爆炸药阻断追兵，以死守住任务的开始。","playerGoals":"逃离检疫区，在FEDRA哨兵间穿行，到达约定地点","newCharacters":"艾莉（主角）、泰丝（乔尔搭档）、玛琳（萤火虫领袖）"},{"id":2,"name":"城郊与比尔的小镇","planet":"林肯镇·马萨诸塞","progressStart":18,"progressEnd":34,"hypeScore":7,"keyEvent":"在比尔处取得车辆，击败体育馆膨胀者","plotDetail":"寻找车辆零件的旅程让乔尔和艾莉穿越废弃小镇，遭遇膨胀者。比尔——一个在孤独中构建了完整防御体系的幸存者——展现了末日中人类另一种选择：彻底封闭自我。","playerGoals":"找到可用车辆，躲避感染者，向西行进","newCharacters":"比尔（独行幸存者）、弗兰克（比尔的遗憾）"},{"id":3,"name":"匹兹堡·亨利与萨姆","planet":"宾夕法尼亚州匹兹堡","progressStart":34,"progressEnd":52,"hypeScore":8,"keyEvent":"邂逅兄弟亨利与萨姆，萨姆感染后以悲剧告终","plotDetail":"匹兹堡被人类幸存者团伙\"猎手\"控制，更危险的反而是活人。乔尔与艾莉结识亨利与萨姆兄弟，四人短暂结伴。最后萨姆向艾莉坦白自己被咬，次日清晨他完全感染，亨利被迫射杀弟弟后自尽。","playerGoals":"穿越猎手控制区，通过下水道，与兄弟二人合作逃脱","newCharacters":"亨利（哥哥·保护者）、萨姆（弟弟·艾莉的朋友）"},{"id":4,"name":"大坝·汤米·大学","planet":"怀俄明州杰克逊 / 科罗拉多大学","progressStart":52,"progressEnd":68,"hypeScore":7,"keyEvent":"与弟弟汤米重逢，大学中乔尔被长矛穿刺重伤","plotDetail":"乔尔找到隐居在怀俄明水电大坝的弟弟汤米，一度想将艾莉转交给他。艾莉拒绝被抛弃后，两人继续同行前往科罗拉多大学寻找萤火虫。然而大学已被废弃，撤退途中乔尔从高处坠落，被铁杆刺穿腹部。","playerGoals":"找到汤米，前往大学，在乔尔重伤后帮艾莉撤退","newCharacters":"汤米（乔尔弟弟）、玛丽亚（汤米妻子）"},{"id":5,"name":"冬季·艾莉独自求生","planet":"科罗拉多山区","progressStart":68,"progressEnd":90,"hypeScore":10,"keyEvent":"艾莉独自猎鹿为乔尔觅食，被大卫俘虏，在燃烧餐厅中击败他","plotDetail":"乔尔重伤昏迷，艾莉独自在雪地中打猎。她被大卫和他的人马俘获——表面上大卫是宗教领袖，实则是食人团伙头目。艾莉趁机逃脱，在燃烧的餐厅中以砍刀结束了大卫的生命。乔尔呼唤她的声音将她从崩溃边缘拉回。","playerGoals":"为乔尔寻找抗生素，从大卫处逃脱，在餐厅中生存","newCharacters":"大卫（最令人不安的人类反派）、詹姆斯（大卫副手）"},{"id":6,"name":"春天·最后的旅程","planet":"犹他州盐湖城","progressStart":90,"progressEnd":100,"hypeScore":10,"keyEvent":"乔尔闯入萤火虫医院，枪杀玛琳，救下艾莉，编下那个改变一切的谎言","plotDetail":"二人终于到达盐湖城萤火虫总部。乔尔得知手术将摘除艾莉的脑部，愤而杀出血路救她。他枪杀了选择放弃的玛琳，逃出医院。清醒后的艾莉追问真相，乔尔说：\"萤火虫放弃了。\"——这个谎言，是《美国末日》续作全部故事的起点。","playerGoals":"找到萤火虫基地，突破医院守卫，做出乔尔的最终抉择","newCharacters":"玛琳（萤火虫领袖，再见）"}],"achievements":[{"steamId":"ACH_TLOU1_PROLOGUE","progressPct":5},{"steamId":"ACH_TLOU1_BOSTON","progressPct":18},{"steamId":"ACH_TLOU1_LINCOLN","progressPct":34},{"steamId":"ACH_TLOU1_PITTSBURGH","progressPct":52},{"steamId":"ACH_TLOU1_TOMMY","progressPct":60},{"steamId":"ACH_TLOU1_UNIVERSITY","progressPct":68},{"steamId":"ACH_TLOU1_WINTER","progressPct":90},{"steamId":"ACH_TLOU1_SPRING","progressPct":100}],"playerSentiment":{"steamScore":71,"source":"Steam 用户评测 & Metacritic & Reddit","note":"PC 版因技术问题首周口碑受损，后续优化后稳定在褒贬不一","keywords":{"praise":["剧情史诗级","乔尔艾莉感情线","配乐令人落泪","艾莉独角戏封神","结局久久回味","大卫反派极品","画面重制惊艳","叙事教科书"],"criticism":["PC移植优化差","主机独占太久","价格偏高","重复性较强","线性流程","DRM保护苛刻"],"hot":["乔尔的谎言对吗","结局是正确选择吗","父爱还是自私","原版vs重制版值吗","萨拉序章催泪弹"]},"testimonials":[{"text":"序章5分钟我就哭了。然后游戏才真正开始。这不公平。","author":"Steam 评测","upvotes":9241},{"text":"乔尔的结局选择：如果你觉得他错了，等你有孩子再说。","author":"Reddit r/thelastofus","upvotes":7832},{"text":"大卫那关我关掉游戏去喝了杯水，缓了10分钟，才敢继续。","author":"Steam 评测","upvotes":4503},{"text":"通关后我对着黑屏坐了很久。我只是不想它结束。","author":"Metacritic 用户评测","upvotes":6127}]}},{"id":"last_of_us_2","name":"The Last of Us Part II Remastered","titleMain":"The Last of Us Part II","titleSub":"最后生还者 第二部","short":"TLOU II","genre":"动作冒险","currentPct":0,"developer":"Naughty Dog","year":2025,"steamAppId":2531310,"totalHoursMain":25,"posterUrl":"assets/covers/last_of_us_2-poster.jpg","bannerUrl":"assets/covers/last_of_us_2-banner.jpg","gameTheme":{"bg":"#0b1008","bgCard":"#111a0d","accent":"#4a8c2a","accent2":"#1e3d0d","text":"#c8e0b0"},"overview":{"tagline":"复仇点燃，但你终将凝视它的另一面","description":"四年后，艾莉生活在怀俄明州的杰克逊，与乔尔的谎言共存。一场突如其来的暴力彻底改变了一切，她踏上了西雅图的复仇之路。然而这款游戏做了一件史无前例的事：它强迫你以\"仇人\"的视角重新经历同样的故事——直到你开始理解，没有人天生是反派。","highlights":[{"icon":"🔄","text":"双主角叙事·颠覆视角"},{"icon":"🐀","text":"鼠王·最惊险的Boss战"},{"icon":"🌿","text":"西雅图·植物侵占的废城"},{"icon":"💀","text":"暴力后果·比前作更黑暗"}]},"entryPoints":[{"progressPct":0,"label":"序章·杰克逊","reason":"必须从头开始——Joel在这里的遭遇是后续一切的动因，错过则失去整个情感逻辑"},{"progressPct":48,"label":"艾比视角开始","reason":"视角切换是本作最大胆的设计，从这里体验\"另一面的故事\"，理解本作核心主题"},{"progressPct":72,"label":"农场·四年后","reason":"短暂宁静后的再次出发，艾莉最终选择的重量在这里完整呈现"}],"protagonistJourney":[{"progressPct":8,"event":"Joel 遭遇·一切的起点","description":"四年和平生活被打破。艾莉目睹了那一刻，愤怒与悲痛点燃了她前往西雅图的决心。","unlocks":["复仇动机确立","第一叙事弧开始"]},{"progressPct":28,"event":"WLF 与锯齿派·西雅图内战","description":"艾莉深陷华盛顿解放阵线（WLF）与宗教武装锯齿派的战争废墟，两方都视她为敌人。","unlocks":["西雅图世界观构建","莱夫·狄娜·杰西登场"]},{"progressPct":45,"event":"水族馆·狄娜与艾莉的抉择","description":"水族馆成为临时庇护所。狄娜告知自己怀孕，两人关系进入新阶段，任务的代价开始显现。","unlocks":["情感代价主题","目标与关系的张力"]},{"progressPct":52,"event":"视角切换·成为\"仇人\"艾比","description":"游戏强制切换至艾比视角，重演西雅图同一段时间线。玩家开始理解这个让所有人恨透的角色的内心。","unlocks":["艾比故事线开始","道德相对主义主题全面展开"]},{"progressPct":65,"event":"鼠王 — 医院地下室","description":"艾比在被真菌融合的医院地下室遭遇鼠王——游戏最恐怖也最震撼的战斗。这一幕重新定义了玩家对艾比的情感。","unlocks":["艾比人物弧高潮","莱夫与艾比羁绊"]},{"progressPct":72,"event":"剧院·艾莉vs艾比，第一次","description":"两条叙事线在剧院交汇，两场复仇走向同一个碰撞点。游戏最具争议的时刻之一就发生在这里。","unlocks":["两条线汇合","结局伏笔全面展开"]},{"progressPct":88,"event":"农场·短暂的宁静与最后的出发","description":"四年后，艾莉和狄娜在农场生活。乔尔的幽灵仍困扰着她，最终她独自踏上了最后的旅程。","unlocks":["艾莉最终选择","尾声弧开始"]},{"progressPct":97,"event":"海滩·最后的相遇与放手","description":"最终决战，两人精疲力竭。艾莉做出了乔尔也许希望她做出的选择。两根断指沉入海水——音乐停止。","unlocks":["全游戏主题收束","宽恕与代价"]}],"hypePeaks":[{"progressPct":8,"label":"Joel 遭遇","score":10,"color":"#ef4444"},{"progressPct":28,"label":"WLF大规模战斗","score":8,"color":"#f97316"},{"progressPct":40,"label":"锯齿派奇袭","score":8,"color":"#ef4444"},{"progressPct":45,"label":"水族馆·狄娜怀孕","score":7,"color":"#a855f7"},{"progressPct":52,"label":"视角切换震撼","score":9,"color":"#a855f7"},{"progressPct":65,"label":"鼠王决战","score":10,"color":"#ef4444"},{"progressPct":72,"label":"剧院·两人对决","score":10,"color":"#ef4444"},{"progressPct":95,"label":"海滩最终对决","score":10,"color":"#ef4444"},{"progressPct":99,"label":"艾莉的选择·放手","score":9,"color":"#a855f7"}],"bossSaves":[{"id":"bloater_bank","name":"膨胀者 — 西雅图银行地窖","planet":"西雅图·市中心","progressPct":28,"storyGap":2,"highlight":false,"context":{"plot":"艾莉与狄娜在西雅图市中心搜查WLF据点时，进入一家废弃银行，银行地下金库区域封锁着一只膨胀者。比起第一部，《Part II》的膨胀者战斗空间更复杂，武器系统更丰富。","characters":"艾莉：比第一部战斗能力更强，有匕首近战、弓箭、瓶子投掷等完整工具链。狄娜：提供火力支援，对话补充气氛。膨胀者：真菌装甲更厚，投掷孢子弹范围更大。","gameplay":"优先用燃烧瓶烧掉装甲块，再集中攻击脆弱点。充分利用空间中的汽油桶和易燃物。本作新增的潜行砍刀可以背刺感染者，但膨胀者免疫潜行即死。","save":"本关卡无社区存档包。银行入口会触发自动存档，建议另存一格保留。"}},{"id":"rat_king","name":"鼠王 — 受感染医院地下室（艾比视角）","planet":"西雅图·医院","progressPct":65,"storyGap":3,"highlight":true,"context":{"plot":"艾比在寻找疫苗研究资料时深入西雅图旧医院地下室，遭遇了游戏中最恐怖的存在：鼠王（Rat King）——多具感染者经年累月融合成的超级生物体，彼此缠绕、呼吸、行动，是一个移动的真菌生态系统。","characters":"鼠王：本作最令人不寒而栗的设计之一。第一阶段是融合体，第二阶段会分裂出一个独立的奔跑者个体继续追杀。艾比：独自面对，这一段是她角色弧线的最高潮。","gameplay":"两阶段战斗。第一阶段：用燃烧瓶、炸弹弓箭持续消耗血量，保持移动不要被拍到。第二阶段：分裂体速度极快，优先击杀分裂体，再集中轰炸本体脆弱部位。弹药充足前不要硬碰。","save":"本关卡无社区存档包。进入地下室时自动存档。鼠王是本作可选难度差异最大的关卡，建议在普通难度先通关再挑战高难度。"}},{"id":"theater_fight","name":"艾莉 vs 艾比 — 西雅图剧院","planet":"西雅图·联盟剧院","progressPct":72,"storyGap":4,"highlight":true,"context":{"plot":"两条叙事线在剧院交汇——艾莉找到了艾比。这是第一次正面对决，也是本作最高争议时刻之一。游戏在这里强迫玩家扮演\"两方\"轮流战斗，彻底挑战了玩家的立场。结果令人咋舌。","characters":"艾莉：复仇的执行者，此刻距目标最近。艾比：已经在她的叙事线里成为了你的主角。杰西：艾莉最好的朋友，他的遭遇撕裂了剧情。","gameplay":"这是一场剧情驱动的Boss战，不是纯粹的技术挑战。重点在于感受而非最优解。根据剧情节奏应对艾比的攻击模式，保持弹反和闪躲。结局是固定的——不管你做什么。","save":"本关卡无社区存档包。进入剧院触发自动存档。建议手动另存，因为后续剧情发展无法逆转。"}},{"id":"beach_final","name":"海滩·最后一战（最终决战）","planet":"加利福尼亚州圣塔芭芭拉","progressPct":98,"storyGap":5,"highlight":true,"context":{"plot":"艾莉在圣塔芭芭拉海滩找到了被关押的艾比与莱夫。最后一场战斗在浅水滩上展开，两人都已精疲力竭、伤痕累累。这是整个游戏的情感终点——复仇还是放手，游戏把这个选择压在最后一刻。","characters":"艾莉：手指已残，吉他再也弹不了。这是她最后一次拥有复仇的机会。艾比：死到临头，仍在保护莱夫。莱夫：艾比救赎的象征，也是让艾莉停手的理由之一。","gameplay":"最终战斗在齐腰深的海水中进行，移动受限。利用水中的漂浮物做掩体，专注躲避艾比的强力攻击。这场战斗很长，但结局是固定的——游戏需要你亲身经历每一刀，才能感受到最后那个选择的重量。","save":"本关卡无社区存档包。圣塔芭芭拉海滩入口触发自动存档。这是游戏最后的存档点，通关后即进入结局动画。"}}],"chapters":[{"id":0,"name":"序章·杰克逊的宁静","planet":"怀俄明州杰克逊","progressStart":0,"progressEnd":10,"hypeScore":8,"keyEvent":"四年后的Joel与Ellie重逢，宁静被彻底打破","plotDetail":"游戏从杰克逊安全区开始，乔尔与艾莉试图修复因上一部谎言产生的裂痕。一场常规巡逻任务被陌生人介入，后果不可挽回。这是本作最重要的叙事基点——你必须看到这里发生了什么，才能理解艾莉后续的一切。","playerGoals":"体验杰克逊的日常生活，跟随巡逻队，目睹关键事件","newCharacters":"狄娜（艾莉的恋人）、杰西（好友）、艾比（神秘陌生人）"},{"id":1,"name":"西雅图第1-2天·艾莉","planet":"华盛顿州西雅图","progressStart":10,"progressEnd":35,"hypeScore":8,"keyEvent":"艾莉进入WLF控制区，第一次与锯齿派正面冲突","plotDetail":"艾莉与狄娜潜入WLF（华盛顿解放阵线）控制的西雅图，寻找目标线索。城市已被植物和感染者侵占，WLF与锯齿派之间的内战让局势更为复杂。艾莉逐渐深陷这场与她无关的战争之中。","playerGoals":"在WLF控制区内侦查，避免两方武装，追踪目标","newCharacters":"WLF队员（敌方）、锯齿派成员（敌方）、梅尔（医疗人员）"},{"id":2,"name":"西雅图第3天·艾莉·水族馆","planet":"西雅图·海滨水族馆","progressStart":35,"progressEnd":50,"hypeScore":9,"keyEvent":"水族馆对峙，WLF内线联络，狄娜怀孕告白","plotDetail":"最终目标即将在手，艾莉却得知狄娜怀孕，任务代价突然变得沉重。锯齿派奇袭打乱了所有计划，艾莉不得不在保护关系与完成复仇之间抉择。巨型水族馆提供了本作最震撼的战场。","playerGoals":"到达水族馆，面对WLF高层，应对锯齿派奇袭","newCharacters":"莱夫（锯齿派少年，第一次出现）"},{"id":3,"name":"西雅图三天·艾比视角","planet":"西雅图·WLF基地及周边","progressStart":50,"progressEnd":75,"hypeScore":10,"keyEvent":"视角切换，艾比的西雅图三天，鼠王对决，剧院最终交汇","plotDetail":"游戏在最高潮处彻底切换视角，让玩家以艾比身份重走西雅图。艾比有自己的朋友、恐惧、痛苦和成长——她和莱夫的羁绊是这一段的情感核心。鼠王是艾比线最高潮的战斗，剧院则是两条线的最终交汇点。","playerGoals":"以艾比身份完成西雅图任务线，击败鼠王，在剧院与艾莉相遇","newCharacters":"莱夫（全面登场）、欧文（艾比旧友）、艾比的回忆·父亲杰里"},{"id":4,"name":"尾声·农场与圣塔芭芭拉","planet":"怀俄明州农场 / 加州圣塔芭芭拉","progressStart":75,"progressEnd":100,"hypeScore":9,"keyEvent":"四年后的宁静生活，最终出发，海滩决战与放手","plotDetail":"四年后，艾莉与狄娜在农场隐居，但乔尔的幽灵让她无法平静。她独自前往圣塔芭芭拉，找到了被奴役的艾比与莱夫。最终海滩决战在精疲力竭中进行——艾莉做出了那个选择。回到空荡荡的农场，吉他静静立在那里，她失去了两根弹弦的手指。","playerGoals":"从农场前往圣塔芭芭拉，解救艾比，进行最终对决，做出选择","newCharacters":"（全部角色弧线收束，无新角色）"}],"achievements":[{"steamId":"ACH_TLOU2_JACKSON","progressPct":10},{"steamId":"ACH_TLOU2_SEATTLE1","progressPct":35},{"steamId":"ACH_TLOU2_AQUARIUM","progressPct":50},{"steamId":"ACH_TLOU2_ABBY1","progressPct":65},{"steamId":"ACH_TLOU2_THEATER","progressPct":75},{"steamId":"ACH_TLOU2_FARM","progressPct":88},{"steamId":"ACH_TLOU2_ENDING","progressPct":100}],"playerSentiment":{"steamScore":78,"source":"Steam 用户评测 & Metacritic & PS5玩家评分 & Reddit","note":"首发口碑两极，随剧透风波沉淀后褒贬趋于平衡，艾比线是核心争议焦点","keywords":{"praise":["双视角叙事革命","艾比线封神","鼠王太恐怖了","配乐宇宙级","画面顶尖","艾莉成长弧完整","道德灰色地带","莱夫太可爱了","西雅图世界构建"],"criticism":["乔尔死法接受不了","剧透毁了体验","艾比不喜欢","视角切换太突然","游戏时长太长","结局意犹未尽","PC版画质设置复杂"],"hot":["乔尔死亡争议","艾比到底对不对","你能理解艾比吗","复仇值得吗","结局艾莉放手了","两部作品哪部更好","莱夫最终去哪了"]},"testimonials":[{"text":"我花了25小时恨一个角色，然后花了15小时理解她，最后花了1小时原谅她。这是一部电影。","author":"Steam 评测","upvotes":8934},{"text":"鼠王关卡结束后我放下手柄，深吸一口气，决定今晚不玩了。","author":"Reddit r/thelastofus","upvotes":6741},{"text":"海滩结局艾莉的选择：第一次看愤怒，第二次看心碎，第三次看懂了。","author":"Metacritic 用户评测","upvotes":5823},{"text":"游戏问你：你能理解你最恨的人吗？我以为不能。它证明了我错了。","author":"Steam 评测","upvotes":7201}]}},{"id":"max_payne_3","name":"Max Payne 3","titleMain":"Max Payne 3","titleSub":"马克思·佩恩 3","short":"Max Payne 3","genre":"第三人称射击","currentPct":0,"nameEn":"Max Payne 3","developer":"Rockstar Games","year":2012,"steamAppId":204100,"totalHoursMain":10,"totalHoursComplete":16,"bannerUrl":"assets/covers/max_payne_3-banner.jpg","posterUrl":"assets/covers/max_payne_3-poster.jpg","overview":{"tagline":"一个男人，一把枪，一段无路可退的旅程","description":"Max Payne 3 是 Rockstar Games 出品的第三人称射击游戏，也是这个系列最成熟、最沉重的篇章。Max Payne——一个被悲剧和酒精蹂躏多年的前纽约警探——来到圣保罗担任保镖，却意外卷入了一场涉及腐败政客、黑帮与人体器官贩卖的巨大阴谋。游戏以慢动作子弹时间为核心机制，以电影级叙事为灵魂，大量第一人称内心独白构成了这个故事最独特的气质：疲惫、犀利、黑色幽默之下是一个孤独男人试图在废墟中找到一点点意义。","highlights":[{"icon":"🎬","text":"电影级叙事：Max 的内心独白是整个游戏的灵魂"},{"icon":"💊","text":"子弹时间系统：慢动作枪战的极致爽感体验"},{"icon":"🏟️","text":"体育场大屠杀——游戏史上最震撼的剧情反转之一"},{"icon":"✈️","text":"机场终章：孤身闯机场，系列最高光的收尾时刻"}]},"entryPoints":[{"progressPct":0,"label":"推荐起点：完整体验","reason":"从头跟随 Max 来到巴西，感受从\"普通保镖工作\"逐渐滑向深渊的完整叙事弧线，游戏前期节奏轻松，是适应机制的最佳方式。"},{"progressPct":43,"label":"剧情加速入口","reason":"Rodrigo 已死，Max 失去一切退路，故事正式进入高速道。从这里开始每一章都有剧情爆炸时刻，枪战难度也恰好进入中等区间。"},{"progressPct":84,"label":"高潮直入——机场前夜","reason":"所有幕后黑手已揭晓，最后的清算开始。这两章是全游戏动作密度和情感张力双峰值，适合只想感受系列高光时刻的玩家。"}],"protagonistJourney":[{"progressPct":0,"event":"圣保罗·落魄雇佣兵","description":"Max 来到巴西，酗酒、潦倒、试图重新开始。他只想做好分内的保镖工作，不再惹麻烦。","unlocks":["子弹时间基础","翻滚射击（Shootdodge）","双枪模式"]},{"progressPct":22,"event":"雇主遇害·无路可退","description":"Rodrigo 死后，Max 失去了工作、金钱和在巴西的立足点。他留下来，不是因为有计划，而是因为他已经没有别的地方可去。","unlocks":["重武器（霰弹枪·突击步枪）","痛苦镇痛剂系统强化","近战处决"]},{"progressPct":50,"event":"体育场·看清真相","description":"Max 目睹了国家机器的暴行。这不再是保镖任务，不再是单纯的复仇——这是一个男人决定站到腐败的对面。","unlocks":["狙击步枪","战术掩体意识","子弹时间连续触发"]},{"progressPct":63,"event":"Victor 真相·彻底孤立","description":"Max 明白了一切都是局，他是被利用的棋子。此刻他不再试图逃离，而是决定把所有人都清算一遍。","unlocks":["重型甲胄穿透弹药","多目标锁定模式"]},{"progressPct":84,"event":"机场·最后的清算","description":"Max 孤身一人，对抗整个体制。没有支援，没有授权，只有愤怒和多年积累的射击本能。这是他在这个故事里最自由的时刻。","unlocks":["全武器库开放","最终子弹时间强化"]}],"gameTheme":{"bg":"#0a0805","bgCard":"#130f0a","accent":"#c8892a","accent2":"#e05c2a","text":"#e8ddd0"},"chapters":[{"id":0,"name":"Ch.1–3：派对与绑架","planet":"圣保罗·上流社会","progressStart":0,"progressEnd":22,"hypeScore":6,"keyEvent":"Max 受雇保护 Rodrigo，在夜店派对上 Fabiana 遭到绑架，一切开始崩坏","plotDetail":"Max 来到巴西，试图用一份保镖工作重新开始。圣保罗上流社会的浮华派对与他满身的沧桑形成强烈对比。工作第一晚，Rodrigo 的妻子 Fabiana 就在夜店遭到武装绑架。Max 来不及反应，绑架者 CS 帮首领 Serrano 已经消失在夜色中。这三章建立了游戏的情感基调：一个已经没有什么可失去的男人，却又开始有了失去的东西。","playerGoals":"在夜店枪战中保护 Rodrigo 家族 → 追踪 Fabiana 的下落 → 击败 Serrano，救援任务初步完成但付出代价","newCharacters":"Max Payne（主角，疲惫的前警探）、Rodrigo Branco（雇主，地产大亨）、Raul Passos（Max 的搭档）、Fabiana（Rodrigo 之妻，绑架受害者）、Serrano（CS 帮首领）"},{"id":1,"name":"Ch.4–6：追踪与背叛","planet":"圣保罗·贫民窟","progressStart":22,"progressEnd":43,"hypeScore":7,"keyEvent":"Max 深入贫民窟，雇主 Rodrigo 遇害，Max 的处境急剧恶化","plotDetail":"贫民窟是圣保罗的另一面——狭窄的巷道、垂直叠层的贫困建筑，和随处可见的武装力量。Max 深入其中追踪绑架线索，却只换来更多的混乱。Rodrigo 遇害是这段故事的分水岭：Max 失去了工作、立足点，甚至失去了在这座城市继续存在的理由。但他还是留了下来。","playerGoals":"追踪 CS 帮到贫民窟据点 → 试图在混乱中保住 Rodrigo 的性命（但失败）→ 在孤立无援的状态下杀出重围","newCharacters":"贫民窟 CS 帮成员、Victor Branco（Rodrigo 的弟弟，首次登场，看似悲痛的受害者）"},{"id":2,"name":"Ch.7–9：真相浮现","planet":"圣保罗·体育场","progressStart":43,"progressEnd":64,"hypeScore":8,"keyEvent":"体育场大屠杀揭示幕后黑手，Max 发现自己卷入了远比想象更深的阴谋","plotDetail":"体育场章节是全游戏最震撼的叙事时刻。Max 追踪人贩网络进入一座巨大的足球场，目睹了 UFE（精英警察）有组织地屠杀平民。这不是帮派暴力，而是国家暴力。Max 此前以为自己在追坏人，现在他发现：合法与非法的界限从未如此模糊。","playerGoals":"深入体育场揭露人贩组织 → 在 UFE 屠杀中存活 → 找到幕后指使的第一条真正线索","newCharacters":"UFE（联邦特种部队，本作最大反派势力）、Giovanna（Passos 的女友，关键角色）"},{"id":3,"name":"Ch.10–12：幕后的阴谋","planet":"圣保罗·港口·机场","progressStart":64,"progressEnd":84,"hypeScore":8,"keyEvent":"Victor Branco 的腐败暴露，UFE 组织真面目浮出，Max 孤身对抗整个体制","plotDetail":"这三章是谜底逐渐揭晓的过程。Victor Branco——那个全程以悲痛家属身份出现的男人——是整个腐败网络的核心策划者。他参与了哥哥的死，他为器官贩卖提供政治保护伞，他利用 UFE 清除异见。Max 在港口的集装箱迷宫和仓库间追踪真相，每一场枪战都让他离清算更近一步。","playerGoals":"追踪 Victor Branco 的幕后指示链 → 在港口激战中生存并收集证据 → 确认最终目标，准备最后的清算","newCharacters":"Becker（UFE 实际指挥官，最终Boss）、Victor Branco（真正的幕后黑手，全面登场）"},{"id":4,"name":"Ch.13–14：最后的复仇","planet":"圣保罗国际机场","progressStart":84,"progressEnd":100,"hypeScore":10,"keyEvent":"Max 独闯机场，清算所有幕后黑手，以一己之力终结这场腐败游戏","plotDetail":"Victor Branco 试图带着罪行和秘密逃离巴西。Max Payne，一个没有授权、没有支援、没有任何退路的中年男人，独自走入圣保罗国际机场。候机楼、登机口、停机坪、跑道——每一步都是对整个腐败体制的正面宣战。这不是英雄时刻，这是一个已经失去了一切的人，用最后的力气在这个世界上留下一个答案。","playerGoals":"穿越机场全区域连续战斗 → 击败 Becker → 追上 Victor Branco，完成最终清算","newCharacters":"无新角色——这是所有线索的终点，是已登场角色各自命运的收尾"}],"hypePeaks":[{"progressPct":15,"label":"Fabiana 被劫","score":7,"color":"#c8892a"},{"progressPct":22,"label":"Rodrigo 遇害","score":7,"color":"#ef4444"},{"progressPct":36,"label":"贫民窟突围","score":7,"color":"#f97316"},{"progressPct":50,"label":"体育场大屠杀","score":9,"color":"#ef4444"},{"progressPct":63,"label":"Victor 真面目","score":8,"color":"#a855f7"},{"progressPct":76,"label":"港口激战","score":8,"color":"#f97316"},{"progressPct":87,"label":"UFE 大本营","score":8,"color":"#ef4444"},{"progressPct":93,"label":"机场最终战","score":10,"color":"#ef4444"},{"progressPct":98,"label":"Max 的告别","score":7,"color":"#a855f7"}],"achievements":[{"steamId":"ACH_CH3_CLEAR","name":"Just Another Friday Night","progressPct":22},{"steamId":"ACH_CH6_CLEAR","name":"A Dame, A Dork, and A Drunk","progressPct":43},{"steamId":"ACH_STADIUM","name":"Ain't No Reprieve","progressPct":57},{"steamId":"ACH_CH9_CLEAR","name":"Halfway Down the World","progressPct":64},{"steamId":"ACH_CH11_CLEAR","name":"Sun Tan Oil","progressPct":79},{"steamId":"ACH_BECKER","name":"One Card Left to Play","progressPct":93},{"steamId":"ACH_END","name":"Out the Window","progressPct":100}],"bossSaves":[{"id":"serrano","name":"Serrano — 夜店枪战","nameEn":"Serrano – Club Desnuda","folder":null,"progressPct":15,"storyGap":1,"planet":"圣保罗·Club Desnuda","highlight":false,"context":{"plot":"Max Payne 离开美国后潦倒失意，酗酒度日。他在老友 Raul Passos 的引荐下来到圣保罗，为巴西富豪 Rodrigo Branco 担任私人保镖。工作的第一个正式夜晚，Rodrigo 的妻子 Fabiana 在高档夜店遭到武装绑架。绑架者是 Comando Sombra（CS 帮）的头目 Serrano——一个在贫民窟崛起的武装犯罪首领。Max 来不及反应，Fabiana 就已经消失在圣保罗的夜色中。","characters":"Max Payne：主角，前纽约警探，被悲剧和酒精蹂躏多年的孤独中年男人。他的内心独白是游戏叙事的核心——犀利、疲惫、带着黑色幽默。\n\nRaul Passos：Max 的搭档兼引荐人，职业雇佣军，冷静务实。\n\nFabiana Branco：Rodrigo 的年轻妻子，美丽而充满活力，她的绑架是整个故事的导火索。\n\nSerrano：CS 帮首领，表面是街头枭雄，实则是更大阴谋的一枚棋子。","gameplay":"Max Payne 3 没有传统意义上的生命值Boss战——Serrano 是一个场景型\"最终敌人\"，在近距离枪战中被击毙。核心机制：子弹时间（Bullet Time）+ 慢动作翻滚（Shootdodge）。这是全游戏的机制入门关，多使用子弹时间，习惯贴墙掩体和动态射击的节奏。"}},{"id":"rodrigo_death","name":"救援失败 — Rodrigo 遇害","nameEn":"Rodrigo Killed – The Penthouse","folder":null,"progressPct":22,"storyGap":1,"planet":"圣保罗·Rodrigo 公寓","highlight":true,"context":{"plot":"Max 经历了贫民窟和夜店的枪战，终于找到了 Fabiana 的下落，但救援计划一再出错。当他赶回 Rodrigo 的豪华公寓时，武装力量已经封锁了整栋大楼。Rodrigo 拒绝逃跑，试图独自对抗——Max 赶到时，只来得及见到他最后一面。雇主的死彻底改变了这个故事的性质：这不再是一个保镖的工作，而是一个男人在异国他乡的个人清算。","characters":"Rodrigo Branco：圣保罗的地产大亨，Max 的雇主。他不是反派，但他在最后关头展现出出人意料的尊严。他的死是 Max 在巴西故事的真正起点。\n\nVictor Branco（Rodrigo 的弟弟）：此时开始逐渐进入故事中心，随后的章节会逐渐揭示他的真实面目。","gameplay":"公寓大楼的垂直战斗——从顶层向下清场，在混乱的房间和走廊中对抗多波武装人员。核心技巧：利用子弹时间穿过门洞的瞬间——开门同时触发慢动作，先敌出枪。这一章开始引入更多敌人同时进攻的场景，学会控制战场节奏。"}},{"id":"stadium","name":"体育场大屠杀","nameEn":"Stadium Massacre","folder":null,"progressPct":50,"storyGap":3,"planet":"圣保罗·Estádio do Galatians","highlight":true,"context":{"plot":"这是全游戏最令人震惊的剧情节点。Max 和 Passos 追踪人贩组织进入一座足球体育场，却亲眼目睹了一场有组织的屠杀：UFC（联邦特种部队，本应是精英警察）正在系统性地杀死被囚禁的平民。这不是犯罪团伙的暴行，而是披着合法外衣的国家暴力。Max 曾以为自己在追踪犯罪分子，此刻他明白：整个腐败网络比想象中更深，而他已经不可能全身而退。","characters":"Giovanna（Passos 的女友）：在体育场章节扮演关键角色，她的存在揭示了 Passos 的内心纠葛和他更深层的动机。\n\nUFE（联邦特种部队）：本应保护公民的精英警察组织，实则是本作最大的反派势力——他们与器官贩卖和政治腐败深度绑定。\n\nVictor Branco（线索深化）：体育场事件让 Max 开始怀疑，这背后是否有更高层的政治势力在撑腰。","gameplay":"体育场关卡是全游戏规模最宏大的战斗序列之一，包含多个连续的大型战斗区域：看台、球场、更衣室、地下通道。UFE 士兵装备精良、反应迅速，比前几章的帮派成员难对付得多。核心：全程保持移动，不要在同一个掩体后停留太久。子弹时间配合翻滚是穿越开阔地带的最佳方式。"}},{"id":"victor_reveal","name":"Victor Branco — 腐败揭露","nameEn":"Victor Branco Confrontation","folder":null,"progressPct":63,"storyGap":3,"planet":"圣保罗·港口仓库","highlight":true,"context":{"plot":"在体育场和港口的层层追踪之后，真相终于完全浮出水面：Victor Branco，Rodrigo 的亲弟弟、看似最悲痛的亲属，实际上是整个腐败网络的核心策划者。他利用自己的政治地位为器官贩卖和 UFE 的暴行提供保护伞，甚至参与策划了哥哥 Rodrigo 的死亡——他的家族仅仅是一颗用来转移注意力的棋子。Max 终于明白了整件事从一开始就是一个针对他的局。","characters":"Victor Branco：全游戏最具欺骗性的反派。他全程以受害者身份出现，温文尔雅，看起来比任何人都更需要保护。真相大白的瞬间是整个游戏叙事最有力的一刻。\n\nPassos（立场分化）：在这个阶段，Passos 和 Max 之间的信任关系开始受到考验——他们的目标和手段是否还一致？","gameplay":"港口章节是全游戏节奏最紧张的关卡之一：狭窄的集装箱迷宫+开阔的码头区域交替出现，需要频繁在近战掩护和开阔地带之间切换战术。UFE 精锐配有护甲，需要多枪才能击倒。优先瞄准头部，或用爆炸物清场。"}},{"id":"airport_finale","name":"机场终战 — 最后的清算","nameEn":"Airport Finale – Becker","folder":null,"progressPct":93,"storyGap":4,"planet":"圣保罗国际机场","highlight":true,"context":{"plot":"这是 Max Payne 3 的终极高潮，也是整个故事最具力量感的收尾。Victor Branco 试图登机出逃，带着他的罪行和秘密消失于世界某个角落。Max Payne，一个已经失去了一切、没有任何退路的中年男人，独自一人追入圣保罗国际机场。他不是警察，没有授权，没有支援，只有一把枪和多年来积累的愤怒。\n\n这段场景是整个 Max Payne 系列的精神注脚：当体制失败了，当法律无能为力了，当所有正当的途径都被腐败堵死了——一个孤独的男人，用子弹时间在混乱中刻写出属于自己的正义。","characters":"Max Payne：此刻的他已经放下了所有。这不是愤怒，不是复仇——是一种疲惫到极致的坚定。他知道这可能是他最后一次战斗，但他还是走了进去。\n\nBecker（最终目标）：Victor 的保镖头目，UFE 的实际指挥官。在层层枪战之后，与他的最终对决是本作最后一道关卡。\n\nVictor Branco（结局）：他最终会得到什么？游戏给出了一个意想不到却非常符合这个系列精神的答案。","gameplay":"全游戏最大规模的连续战斗区域：候机楼大厅→登机口→停机坪→飞机跑道。大量 UFE 精锐持续增援，全程高压。与 Becker 的最终对决是近距离的子弹时间枪战，他会频繁走位并使用掩体——跟随他的走位节奏，在他换弹时触发子弹时间进行精准狙杀。这场戏的电影感是全系列巅峰，享受它。"}}],"playerSentiment":{"steamScore":85,"source":"Steam 用户评测 & Metacritic & Reddit","note":"首发备受好评，随年代沉淀评价愈发正面，子弹时间系统被视为同类天花板","keywords":{"praise":["子弹时间神作","动作镜头电影感","Max人物塑造极深","配乐极具氛围","圣保罗世界观独特","Rockstar叙事水准","枪感顶尖","结局大快人心"],"criticism":["过场太长不可跳过","Max太惨了受不了","线性流程重复感","章节间节奏不均","多人模式已死"],"hot":["秃头Max还是长发Max","巴西场景太压抑","这是最好的Max Payne吗","过场动画跳不过真的烦","值得重温的神作"]},"testimonials":[{"text":"Max Payne 3是一部关于中年危机的杰作，恰好套着枪战游戏的壳。","author":"Steam 评测","upvotes":3421},{"text":"子弹时间慢动作里看见Max那张沧桑的脸，我突然觉得人生很难。","author":"Reddit r/maxpayne","upvotes":2876},{"text":"过场动画不能跳过——Rockstar的自信，和我的愤怒，旗鼓相当。","author":"Steam 评测","upvotes":5103},{"text":"圣保罗机场最后那段，Max一个人干掉整个军队。电影级的落幕，我鼓掌了。","author":"Metacritic 用户评测","upvotes":1984}]}}];
